// Assemble the app-facing schema; English ingredient lines stay parser-ready.
function mk(s) {
  const ingredients = {};
  LANGS.forEach(l => {
    ingredients[l] = s.ing.map(it => {
      const qty = it.q != null ? String(it.q) : '';
      const unit = it.u ? unitStr(it.u, it.q, l) : '';
      return [qty, unit, it.n[l] || it.n.en].filter(Boolean).join(' ');
    });
  });
  return {
    id: s.id, name: s.name, origin: RO_ORIGIN, category: CAT,
    servings: s.servings, time: { prepMin: s.prep, cookMin: s.cook },
    costRon: s.costRon, nutrition: s.nut, tags: s.tags,
    ingredients, howIsMade: s.steps,
  };
}

const SPECS = [
  { id:'budget_001', name:NAMES.ciorba, servings:2, prep:15, cook:70, costRon:5, nut:{cal:320,prot:16,carb:50,fat:6,fib:14}, tags:['budget','vegan','healthy'],
    ing:[ {q:200,u:'g',n:I.whiteBeans}, {q:1,n:I.onion}, {q:1,n:I.carrot}, {q:100,u:'g',n:I.celery}, {q:2,u:'tbsp',n:I.oil}, {q:1,u:'tsp',n:I.paprika}, {q:2,u:'tbsp',n:I.passata}, {q:1,n:I.bayLeaf}, {q:1.5,u:'l',n:I.water}, {q:1,n:I.lemon}, {q:2,u:'tbsp',n:I.parsley}, {n:I.salt} ],
    steps:{
      ro:'Dacă folosești fasole uscată, las-o peste noapte în apă rece, apoi scurge-o. Pune fasolea într-o oală mare cu apă proaspătă, dă în clocot, ia spuma cu o lingură și fierbe circa 45 de minute, până e aproape moale. Între timp, toacă mărunt ceapa, morcovul și țelina și călește-le în ulei 5 minute, apoi adaugă boiaua și roșiile pasate și mai gătește 2 minute. Pune această bază peste fasole împreună cu foaia de dafin și un praf bun de sare și fierbe încă 20 de minute, până fasolea e moale, iar ciorba prinde corp. Acrește după gust cu zeamă de lămâie — asta o face „ciorbă" — și potrivește sarea. Presară pătrunjel tocat și servește fierbinte, cu pâine.',
      en:'If using dried beans, soak them overnight in cold water, then drain. Put the beans in a large pot with fresh water, bring to a boil, skim off the foam, and simmer for about 45 minutes until nearly tender. Meanwhile, finely chop the onion, carrot and celery and soften them in the oil for 5 minutes, then stir in the paprika and tomato passata and cook for 2 more minutes. Add this base to the beans with the bay leaf and a good pinch of salt, and simmer for another 20 minutes, until the beans are soft and the soup has body. Sour it to taste with a squeeze of lemon — this is what makes it a ciorbă — and adjust the salt. Scatter over the chopped parsley and serve hot with bread.',
      es:'Si usas alubias secas, remójalas toda la noche en agua fría y escúrrelas. Ponlas en una olla grande con agua limpia, lleva a ebullición, retira la espuma y cuece unos 45 minutos hasta que estén casi tiernas. Mientras, pica fino la cebolla, la zanahoria y el apio y sofríelos en el aceite 5 minutos, luego añade el pimentón y el tomate y cocina 2 minutos más. Agrega esta base a las alubias con la hoja de laurel y una buena pizca de sal, y cuece otros 20 minutos, hasta que estén blandas y la sopa tenga cuerpo. Acidúlala al gusto con un chorro de limón —eso la convierte en ciorbă— y ajusta la sal. Espolvorea el perejil picado y sirve caliente con pan.',
      fr:'Si vous utilisez des haricots secs, faites-les tremper une nuit à l’eau froide, puis égouttez. Mettez-les dans une grande casserole d’eau fraîche, portez à ébullition, écumez et laissez mijoter environ 45 minutes jusqu’à ce qu’ils soient presque tendres. Pendant ce temps, hachez finement l’oignon, la carotte et le céleri et faites-les revenir dans l’huile 5 minutes, puis ajoutez le paprika et les tomates passées et poursuivez 2 minutes. Ajoutez cette base aux haricots avec la feuille de laurier et une bonne pincée de sel, et laissez mijoter encore 20 minutes, jusqu’à ce que les haricots soient tendres et la soupe ait du corps. Acidulez au goût d’un filet de citron — c’est ce qui en fait une ciorbă — et rectifiez le sel. Parsemez de persil haché et servez chaud avec du pain.',
      de:'Bei getrockneten Bohnen diese über Nacht in kaltem Wasser einweichen und abgießen. Die Bohnen mit frischem Wasser in einen großen Topf geben, aufkochen, den Schaum abschöpfen und etwa 45 Minuten köcheln, bis sie fast weich sind. Währenddessen Zwiebel, Karotte und Sellerie fein hacken und im Öl 5 Minuten anschwitzen, dann Paprikapulver und passierte Tomaten einrühren und 2 Minuten weiterkochen. Diese Basis mit dem Lorbeerblatt und einer guten Prise Salz zu den Bohnen geben und weitere 20 Minuten köcheln, bis die Bohnen weich sind und die Suppe Körper hat. Nach Geschmack mit einem Spritzer Zitrone säuern — das macht sie zur Ciorbă — und salzen. Mit gehackter Petersilie bestreuen und heiß mit Brot servieren.',
      pt:'Se usar feijão seco, demolhe-o de um dia para o outro em água fria e escorra. Coloque o feijão numa panela grande com água fresca, deixe ferver, retire a espuma e cozinhe cerca de 45 minutos até ficar quase macio. Entretanto, pique fino a cebola, a cenoura e o aipo e refogue no óleo 5 minutos, depois junte o colorau e o tomate passata e cozinhe mais 2 minutos. Junte esta base ao feijão com a folha de louro e uma boa pitada de sal, e cozinhe mais 20 minutos, até o feijão ficar macio e a sopa ganhar corpo. Acidule a gosto com sumo de limão — é o que a torna uma ciorbă — e acerte o sal. Polvilhe com salsa picada e sirva quente com pão.',
      ru:'Если используете сухую фасоль, замочите её на ночь в холодной воде и слейте. Положите фасоль в большую кастрюлю со свежей водой, доведите до кипения, снимите пену и варите около 45 минут почти до мягкости. Тем временем мелко нарежьте лук, морковь и сельдерей и обжарьте в масле 5 минут, затем вмешайте паприку и протёртые томаты и готовьте ещё 2 минуты. Добавьте эту основу к фасоли с лавровым листом и хорошей щепоткой соли и варите ещё 20 минут, пока фасоль не станет мягкой, а суп — насыщенным. Подкислите по вкусу соком лимона — именно это делает его чорбой — и посолите. Посыпьте рубленой петрушкой и подавайте горячим с хлебом.',
      ar:'إن استخدمت الفاصوليا الجافة، انقعها ليلة كاملة في ماء بارد ثم صفّها. ضع الفاصوليا في قدر كبير مع ماء جديد، اغلها وأزل الرغوة، واطهها نحو 45 دقيقة حتى تقترب من النضج. في هذه الأثناء افرم البصل والجزر والكرفس ناعماً وشوّحها في الزيت 5 دقائق، ثم أضف البابريكا والطماطم المهروسة واطهها دقيقتين إضافيتين. أضف هذا الأساس إلى الفاصوليا مع ورقة الغار ورشة ملح جيدة، واطهها 20 دقيقة أخرى حتى تلين الفاصوليا وتكتسب الشوربة قواماً. حمّضها حسب الذوق بعصير الليمون — وهذا ما يجعلها «تشوربا» — واضبط الملح. انثر البقدونس المفروم وقدّمها ساخنة مع الخبز.',
      zh:'若用干豆，先用冷水浸泡一夜后沥干。把豆子放入大锅加清水煮开，撇去浮沫，小火煮约45分钟至将熟。同时把洋葱、胡萝卜和芹菜切碎，用油炒5分钟，加入红椒粉和番茄泥再炒2分钟。将这个底料连同香叶和一大撮盐一起倒入豆子中，再煮20分钟，至豆软、汤浓。按口味挤入柠檬汁增酸——这正是它成为“酸汤（ciorbă）”的关键——再调盐。撒上切碎的欧芹，趁热配面包食用。',
      ja:'乾燥豆を使う場合は一晩冷水に浸してから水を切る。豆を大きめの鍋に入れて新しい水を注ぎ、沸騰させてアクを取り、約45分ほぼ柔らかくなるまで煮る。その間に玉ねぎ、にんじん、セロリをみじん切りにして油で5分炒め、パプリカとトマトピューレを加えてさらに2分炒める。このベースを豆にローリエと塩ひとつまみとともに加え、さらに20分、豆が柔らかくスープにコクが出るまで煮る。好みでレモンを搾って酸味をつける——これが「チョルバ」たるゆえん——塩で調える。刻んだパセリを散らし、パンを添えて熱いうちに供する。',
      hi:'सूखी बीन्स इस्तेमाल कर रहे हों तो रातभर ठंडे पानी में भिगोकर छान लें। बीन्स को बड़े बर्तन में ताज़े पानी के साथ डालकर उबालें, झाग हटाएँ और लगभग 45 मिनट लगभग नरम होने तक पकाएँ। इस बीच प्याज़, गाजर और सेलेरी बारीक काटकर तेल में 5 मिनट भूनें, फिर पेपरिका और टमाटर प्यूरी डालकर 2 मिनट और पकाएँ। यह बेस बीन्स में तेज पत्ता और अच्छी चुटकी नमक के साथ डालें और 20 मिनट और पकाएँ, जब तक बीन्स नरम और सूप गाढ़ा हो। स्वादानुसार नींबू निचोड़कर खट्टा करें — यही इसे „चोरबा" बनाता है — और नमक ठीक करें। कटा हरा धनिया छिड़कें और ब्रेड के साथ गरम परोसें।',
      tr:'Kuru fasulye kullanıyorsanız gece boyu soğuk suda ıslatıp süzün. Fasulyeyi büyük bir tencerede taze suyla kaynatın, köpüğünü alın ve neredeyse yumuşayana dek yaklaşık 45 dakika pişirin. Bu sırada soğan, havuç ve kerevizi ince doğrayıp yağda 5 dakika kavurun, sonra toz biberi ve domates püresini ekleyip 2 dakika daha pişirin. Bu harcı defne yaprağı ve iyi bir tutam tuzla fasulyeye ekleyin ve fasulye yumuşayıp çorba kıvam alana dek 20 dakika daha pişirin. Damak tadınıza göre limon sıkarak ekşitin — onu „çorba" yapan budur — ve tuzu ayarlayın. Kıyılmış maydanoz serpip ekmekle sıcak servis edin.',
      it:'Se usi fagioli secchi, mettili in ammollo una notte in acqua fredda, poi scola. Metti i fagioli in una pentola capiente con acqua fresca, porta a bollore, schiuma e fai sobbollire circa 45 minuti finché sono quasi teneri. Intanto trita fine cipolla, carota e sedano e falli appassire nell’olio 5 minuti, poi unisci la paprica e la passata e cuoci altri 2 minuti. Aggiungi questa base ai fagioli con l’alloro e una buona presa di sale, e fai sobbollire altri 20 minuti, finché i fagioli sono morbidi e la zuppa ha corpo. Acidula a piacere con una spremuta di limone — è ciò che la rende una ciorbă — e regola il sale. Cospargi di prezzemolo tritato e servi calda con pane.',
      ko:'말린 콩을 쓰면 찬물에 하룻밤 불린 뒤 물을 뺀다. 콩을 큰 냄비에 새 물과 함께 넣고 끓여 거품을 걷어내고 약 45분간 거의 익을 때까지 끓인다. 그동안 양파, 당근, 셀러리를 곱게 다져 기름에 5분 볶고 파프리카 가루와 토마토 퓌레를 넣어 2분 더 볶는다. 이 베이스를 월계수 잎, 소금 넉넉히 한 꼬집과 함께 콩에 넣고 콩이 부드러워지고 국물에 깊이가 생길 때까지 20분 더 끓인다. 기호대로 레몬을 짜 신맛을 낸다 — 이것이 „초르버"를 만드는 핵심이다 — 소금으로 간한다. 다진 파슬리를 뿌려 빵과 함께 뜨겁게 낸다.' } },

  { id:'budget_002', name:NAMES.tocanita, servings:2, prep:10, cook:30, costRon:3, nut:{cal:350,prot:7,carb:60,fat:10,fib:6}, tags:['budget','vegan','one-pot'],
    ing:[ {q:600,u:'g',n:I.potatoes}, {q:1,n:I.onion}, {q:2,u:'tbsp',n:I.oil}, {q:1,u:'tsp',n:I.paprika}, {q:2,u:'clove',n:I.garlic}, {q:150,u:'g',n:I.passata}, {q:1,n:I.bayLeaf}, {q:300,u:'ml',n:I.water}, {n:I.salt} ],
    steps:{
      ro:'Curăță cartofii și taie-i cuburi de o îmbucătură. Încălzește uleiul într-o oală și călește ceapa tocată la foc mediu 5 minute, până se înmoaie și se rumenește. Adaugă boiaua și usturoiul și amestecă 30 de secunde — nu lăsa boiaua să ardă, că amărăște — apoi pune roșiile pasate și foaia de dafin. Adaugă cartofii, apa și un praf bun de sare, amestecă să se acopere, apoi fierbe acoperit, la foc mic, circa 25 de minute, până cartofii sunt fragezi și sosul s-a legat. Scutură oala din când în când în loc să amesteci tare, ca să rămână cartofii întregi. Servește fierbinte, simplu sau cu o lingură de smântână, dacă ai.',
      en:'Peel the potatoes and cut them into bite-sized chunks. Warm the oil in a pot and cook the chopped onion over medium heat for 5 minutes, until soft and golden. Stir in the paprika and garlic and cook for 30 seconds — don’t let the paprika burn or it turns bitter — then add the tomato passata and bay leaf. Add the potatoes, water and a good pinch of salt, stir to coat, then simmer covered over low heat for about 25 minutes, until the potatoes are tender and the sauce has thickened. Shake the pot now and then rather than stirring hard, so the potatoes stay whole. Serve hot, on its own or with a spoon of soured cream if you have it.',
      es:'Pela las patatas y córtalas en trozos de un bocado. Calienta el aceite en una olla y sofríe la cebolla picada a fuego medio 5 minutos, hasta que esté blanda y dorada. Añade el pimentón y el ajo y remueve 30 segundos —no dejes que el pimentón se queme o amarga— luego incorpora el tomate y la hoja de laurel. Añade las patatas, el agua y una buena pizca de sal, remueve para cubrir y cuece tapado a fuego bajo unos 25 minutos, hasta que las patatas estén tiernas y la salsa haya espesado. Agita la olla de vez en cuando en lugar de remover fuerte, para que las patatas queden enteras. Sirve caliente, solo o con una cucharada de nata agria si tienes.',
      fr:'Épluchez les pommes de terre et coupez-les en morceaux d’une bouchée. Chauffez l’huile dans une casserole et faites revenir l’oignon haché à feu moyen 5 minutes, jusqu’à ce qu’il soit tendre et doré. Ajoutez le paprika et l’ail et remuez 30 secondes — sans laisser brûler le paprika, sinon il devient amer — puis ajoutez les tomates passées et la feuille de laurier. Ajoutez les pommes de terre, l’eau et une bonne pincée de sel, mélangez pour enrober, puis laissez mijoter à couvert à feu doux environ 25 minutes, jusqu’à ce que les pommes de terre soient tendres et la sauce épaissie. Secouez la casserole de temps en temps plutôt que de remuer fort, pour garder les pommes de terre entières. Servez chaud, seul ou avec une cuillerée de crème aigre si vous en avez.',
      de:'Die Kartoffeln schälen und in mundgerechte Stücke schneiden. Das Öl in einem Topf erwärmen und die gehackte Zwiebel bei mittlerer Hitze 5 Minuten anschwitzen, bis sie weich und goldbraun ist. Paprikapulver und Knoblauch einrühren und 30 Sekunden anrösten — das Paprikapulver nicht verbrennen lassen, sonst wird es bitter — dann passierte Tomaten und Lorbeerblatt zugeben. Kartoffeln, Wasser und eine gute Prise Salz zugeben, umrühren, dann zugedeckt bei niedriger Hitze etwa 25 Minuten köcheln, bis die Kartoffeln weich sind und die Soße gebunden ist. Den Topf ab und zu schwenken statt kräftig zu rühren, damit die Kartoffeln ganz bleiben. Heiß servieren, pur oder mit einem Löffel Schmand, falls vorhanden.',
      pt:'Descasque as batatas e corte-as em pedaços de uma dentada. Aqueça o óleo numa panela e refogue a cebola picada em lume médio 5 minutos, até ficar macia e dourada. Junte o colorau e o alho e mexa 30 segundos — não deixe o colorau queimar, senão amarga — depois adicione o tomate passata e a folha de louro. Junte as batatas, a água e uma boa pitada de sal, mexa para envolver e cozinhe tapado em lume brando cerca de 25 minutos, até as batatas ficarem macias e o molho engrossar. Abane a panela de vez em quando em vez de mexer com força, para as batatas ficarem inteiras. Sirva quente, simples ou com uma colher de natas azedas se tiver.',
      ru:'Очистите картофель и нарежьте кусочками на один укус. Разогрейте масло в кастрюле и обжарьте нарезанный лук на среднем огне 5 минут, до мягкости и золотистости. Вмешайте паприку и чеснок и готовьте 30 секунд — не дайте паприке подгореть, иначе будет горчить — затем добавьте протёртые томаты и лавровый лист. Добавьте картофель, воду и хорошую щепотку соли, перемешайте, затем тушите под крышкой на слабом огне около 25 минут, пока картофель не станет мягким, а соус не загустеет. Время от времени встряхивайте кастрюлю вместо энергичного помешивания, чтобы картофель остался целым. Подавайте горячим, сам по себе или с ложкой сметаны, если есть.',
      ar:'قشّر البطاطس وقطّعها مكعبات بحجم اللقمة. سخّن الزيت في قدر وشوّح البصل المفروم على نار متوسطة 5 دقائق حتى يلين ويكتسب لوناً ذهبياً. أضف البابريكا والثوم وقلّب 30 ثانية — دون أن تحترق البابريكا وإلا صارت مرّة — ثم أضف الطماطم المهروسة وورقة الغار. أضف البطاطس والماء ورشة ملح جيدة، قلّب حتى تتغلّف، ثم اطهها مغطاة على نار هادئة نحو 25 دقيقة حتى تنضج البطاطس وتتماسك الصلصة. هزّ القدر بين الحين والآخر بدل التقليب القوي كي تبقى البطاطس كاملة. قدّمها ساخنة، وحدها أو مع ملعقة قشدة حامضة إن توفّرت.',
      zh:'土豆去皮，切成一口大小的块。锅中热油，中火炒切碎的洋葱5分钟，至变软金黄。加入红椒粉和蒜炒30秒——别让红椒粉烧焦，否则发苦——再加入番茄泥和香叶。放入土豆、水和一大撮盐，翻拌均匀，然后加盖小火煮约25分钟，至土豆软、汤汁收浓。中途晃动锅子而不要用力翻搅，让土豆保持完整。趁热食用，可单吃或加一勺酸奶油。',
      ja:'じゃがいもの皮をむき、一口大に切る。鍋に油を温め、みじん切りの玉ねぎを中火で5分、柔らかく色づくまで炒める。パプリカとにんにくを加えて30秒炒め——パプリカは焦がすと苦くなるので注意——トマトピューレとローリエを加える。じゃがいも、水、塩ひとつまみを入れて全体を混ぜ、ふたをして弱火で約25分、じゃがいもが柔らかくソースがまとまるまで煮る。強くかき混ぜず時々鍋をゆすって、じゃがいもを崩さないようにする。そのまま、あるいはあればサワークリームを添えて熱いうちに供する。',
      hi:'आलू छीलकर एक-निवाले के टुकड़ों में काटें। बर्तन में तेल गरम करें और कटा प्याज़ मध्यम आँच पर 5 मिनट नरम-सुनहरा होने तक भूनें। पेपरिका और लहसुन डालकर 30 सेकंड चलाएँ — पेपरिका जलने न दें वरना कड़वी हो जाती है — फिर टमाटर प्यूरी और तेज पत्ता डालें। आलू, पानी और अच्छी चुटकी नमक डालें, लपेटने के लिए मिलाएँ, फिर ढककर धीमी आँच पर लगभग 25 मिनट पकाएँ जब तक आलू नरम और सॉस गाढ़ी हो। तेज़ चलाने के बजाय बीच-बीच में बर्तन हिलाएँ ताकि आलू साबुत रहें। गरम, अकेले या एक चम्मच खट्टी क्रीम के साथ परोसें।',
      tr:'Patatesleri soyup lokma büyüklüğünde doğrayın. Tencerede yağı ısıtın ve doğranmış soğanı orta ateşte 5 dakika, yumuşayıp kızarana dek kavurun. Toz biber ve sarımsağı ekleyip 30 saniye karıştırın — toz biberi yakmayın, yoksa acılaşır — sonra domates püresi ve defne yaprağını ekleyin. Patatesleri, suyu ve iyi bir tutam tuzu ekleyip harmanlayın, ardından kapağını kapatıp kısık ateşte yaklaşık 25 dakika, patatesler yumuşayıp sos koyulaşana dek pişirin. Sert karıştırmak yerine ara sıra tencereyi sallayın ki patatesler bütün kalsın. Sıcak, tek başına ya da varsa bir kaşık ekşi krema ile servis edin.',
      it:'Sbuccia le patate e tagliale a pezzi di un boccone. Scalda l’olio in una pentola e rosola la cipolla tritata a fuoco medio per 5 minuti, finché è morbida e dorata. Unisci la paprica e l’aglio e mescola 30 secondi — non far bruciare la paprica, o diventa amara — poi aggiungi la passata e l’alloro. Aggiungi le patate, l’acqua e una buona presa di sale, mescola per insaporire, poi cuoci coperto a fuoco basso circa 25 minuti, finché le patate sono tenere e il sugo si è addensato. Scuoti la pentola ogni tanto invece di mescolare con forza, così le patate restano intere. Servi caldo, da solo o con un cucchiaio di panna acida se ce l’hai.',
      ko:'감자는 껍질을 벗겨 한입 크기로 썬다. 냄비에 기름을 데우고 다진 양파를 중불에서 5분간 부드럽고 노릇해질 때까지 볶는다. 파프리카 가루와 마늘을 넣고 30초 볶는다 — 파프리카는 태우면 쓴맛이 나니 주의 — 토마토 퓌레와 월계수 잎을 넣는다. 감자, 물, 소금 넉넉히 한 꼬집을 넣어 고루 섞은 뒤 뚜껑을 덮어 약불에서 약 25분간 감자가 부드럽고 소스가 걸쭉해질 때까지 끓인다. 세게 젓지 말고 가끔 냄비를 흔들어 감자가 부서지지 않게 한다. 그대로 또는 있으면 사워크림 한 숟갈과 함께 뜨겁게 낸다.' } },

  { id:'budget_003', name:NAMES.iahnie, servings:2, prep:10, cook:25, costRon:4, nut:{cal:340,prot:16,carb:48,fat:9,fib:13}, tags:['budget','vegan','high-protein'],
    ing:[ {q:400,u:'g',n:I.beans}, {q:1,n:I.onion}, {q:2,u:'tbsp',n:I.oil}, {q:2,u:'clove',n:I.garlic}, {q:1,u:'tsp',n:I.paprika}, {q:150,u:'g',n:I.passata}, {q:1,n:I.bayLeaf}, {n:I.salt} ],
    steps:{
      ro:'Încălzește uleiul într-o oală și călește ceapa tocată mărunt la foc mediu circa 6 minute, până se înmoaie și se rumenește frumos — o ceapă bine gătită e sufletul acestui fel. Adaugă usturoiul și boiaua și amestecă 30 de secunde, apoi pune roșiile pasate și foaia de dafin și lasă să dea în clocot 3 minute. Scurge și clătește fasolea, adaug-o în oală cu un strop de apă și fierbe blând 15 minute, ca să se pătrundă de arome. Zdrobește câteva boabe de peretele oalei ca să îngroși sosul într-o tocană cremoasă. Potrivește de sare și mai adaugă puțină apă dacă se leagă prea tare. Servește caldă, tradițional cu murături sau pâine.',
      en:'Warm the oil in a pot and cook the finely chopped onion over medium heat for about 6 minutes, until soft and nicely golden — a well-cooked onion is the backbone of this dish. Add the garlic and paprika and stir for 30 seconds, then add the tomato passata and bay leaf and let it bubble for 3 minutes. Drain and rinse the beans, add them to the pot with a splash of water, and simmer gently for 15 minutes so they take on the flavour. Mash a few beans against the side of the pot to thicken the sauce into a creamy stew. Season with salt to taste, and add a little water if it gets too thick. Serve warm, traditionally with pickles or bread.',
      es:'Calienta el aceite en una olla y sofríe la cebolla picada fina a fuego medio unos 6 minutos, hasta que esté blanda y bien dorada —una cebolla bien hecha es el alma de este plato—. Añade el ajo y el pimentón y remueve 30 segundos, luego incorpora el tomate y la hoja de laurel y deja borbotear 3 minutos. Escurre y enjuaga las alubias, añádelas con un chorrito de agua y cuece suave 15 minutos para que tomen sabor. Aplasta unas alubias contra la olla para espesar la salsa en un guiso cremoso. Sazona con sal y añade un poco de agua si queda muy espeso. Sirve caliente, tradicionalmente con encurtidos o pan.',
      fr:'Chauffez l’huile dans une casserole et faites revenir l’oignon finement haché à feu moyen environ 6 minutes, jusqu’à ce qu’il soit tendre et bien doré — un oignon bien cuit est l’âme de ce plat. Ajoutez l’ail et le paprika et remuez 30 secondes, puis ajoutez les tomates passées et la feuille de laurier et laissez bouillonner 3 minutes. Égouttez et rincez les haricots, ajoutez-les avec un peu d’eau et laissez mijoter doucement 15 minutes pour qu’ils s’imprègnent. Écrasez quelques haricots contre la casserole pour épaissir la sauce en un ragoût crémeux. Salez et ajoutez un peu d’eau si c’est trop épais. Servez chaud, traditionnellement avec des pickles ou du pain.',
      de:'Das Öl in einem Topf erwärmen und die fein gehackte Zwiebel bei mittlerer Hitze etwa 6 Minuten anschwitzen, bis sie weich und schön goldbraun ist — eine gut gegarte Zwiebel ist das Rückgrat dieses Gerichts. Knoblauch und Paprikapulver zugeben und 30 Sekunden rühren, dann passierte Tomaten und Lorbeerblatt zugeben und 3 Minuten blubbern lassen. Die Bohnen abtropfen und abspülen, mit einem Schuss Wasser in den Topf geben und 15 Minuten sanft köcheln, damit sie Geschmack aufnehmen. Ein paar Bohnen am Topfrand zerdrücken, um die Soße zu einem cremigen Eintopf zu binden. Mit Salz abschmecken und bei Bedarf etwas Wasser zugeben. Warm servieren, traditionell mit Eingelegtem oder Brot.',
      pt:'Aqueça o óleo numa panela e refogue a cebola bem picada em lume médio cerca de 6 minutos, até ficar macia e bem dourada — uma cebola bem feita é a alma deste prato. Junte o alho e o colorau e mexa 30 segundos, depois adicione o tomate passata e a folha de louro e deixe borbulhar 3 minutos. Escorra e lave o feijão, junte-o com um pouco de água e cozinhe brandamente 15 minutos para absorver o sabor. Esmague alguns grãos contra a panela para engrossar o molho num guisado cremoso. Tempere com sal e junte um pouco de água se ficar muito espesso. Sirva quente, tradicionalmente com picles ou pão.',
      ru:'Разогрейте масло в кастрюле и обжарьте мелко нарезанный лук на среднем огне около 6 минут, до мягкости и красивой золотистости — хорошо приготовленный лук основа этого блюда. Добавьте чеснок и паприку, помешивайте 30 секунд, затем добавьте протёртые томаты и лавровый лист и дайте побулькать 3 минуты. Слейте и промойте фасоль, добавьте её с небольшим количеством воды и тушите на слабом огне 15 минут, чтобы она пропиталась вкусом. Разомните несколько фасолин о стенку кастрюли, чтобы соус загустел в кремовое рагу. Посолите по вкусу и добавьте немного воды, если станет слишком густо. Подавайте тёплым, традиционно с соленьями или хлебом.',
      ar:'سخّن الزيت في قدر وشوّح البصل المفروم ناعماً على نار متوسطة نحو 6 دقائق حتى يلين ويكتسب لوناً ذهبياً جميلاً — البصل المطهو جيداً هو روح هذا الطبق. أضف الثوم والبابريكا وقلّب 30 ثانية، ثم أضف الطماطم المهروسة وورقة الغار واتركها تغلي 3 دقائق. صفّ الفاصوليا واغسلها، أضفها مع رشة ماء واطهها بهدوء 15 دقيقة لتتشرّب النكهة. اهرس بعض الحبات على جدار القدر لتكثيف الصلصة إلى يخنة كريمية. تبّل بالملح وأضف قليلاً من الماء إن ثخنت كثيراً. قدّمها دافئة، وتقليدياً مع المخللات أو الخبز.',
      zh:'锅中热油，中火炒切碎的洋葱约6分钟，至变软、金黄漂亮——炒透的洋葱是这道菜的灵魂。加入蒜和红椒粉炒30秒，再加番茄泥和香叶，煮沸3分钟。豆子沥干冲洗后连同少许水下锅，小火煮15分钟入味。用勺把几颗豆子压在锅壁上，使汤汁浓稠、口感绵密。加盐调味，太稠就加一点水。趁热食用，传统上配腌菜或面包。',
      ja:'鍋に油を温め、みじん切りの玉ねぎを中火で約6分、柔らかくきれいな飴色になるまで炒める——よく炒めた玉ねぎがこの料理の要。にんにくとパプリカを加えて30秒炒め、トマトピューレとローリエを加えて3分ふつふつ煮る。豆を水切りして洗い、水少々とともに鍋に加えて15分ほど静かに煮て味を含ませる。豆を数粒だけ鍋肌でつぶし、ソースにとろみをつけてクリーミーな煮込みにする。塩で味を調え、固くなりすぎたら水を少し足す。温かいうちに、伝統的にはピクルスやパンを添えて供する。',
      hi:'बर्तन में तेल गरम करें और बारीक कटा प्याज़ मध्यम आँच पर लगभग 6 मिनट नरम और अच्छा सुनहरा होने तक भूनें — अच्छी भुनी प्याज़ इस व्यंजन की जान है। लहसुन और पेपरिका डालकर 30 सेकंड चलाएँ, फिर टमाटर प्यूरी और तेज पत्ता डालकर 3 मिनट उबलने दें। बीन्स को छानकर धोएँ, थोड़े पानी के साथ बर्तन में डालें और 15 मिनट धीमी आँच पर पकाएँ ताकि स्वाद सोख लें। कुछ बीन्स को बर्तन की दीवार पर दबाकर मसलें ताकि सॉस गाढ़ी-मलाईदार सालन बने। नमक डालें और ज़्यादा गाढ़ा होने पर थोड़ा पानी मिलाएँ। गरम, परंपरागत रूप से अचार या ब्रेड के साथ परोसें।',
      tr:'Tencerede yağı ısıtın ve ince doğranmış soğanı orta ateşte yaklaşık 6 dakika, yumuşayıp güzelce kızarana dek kavurun — iyi kavrulmuş soğan bu yemeğin ruhudur. Sarımsak ve toz biberi ekleyip 30 saniye karıştırın, sonra domates püresi ve defne yaprağını ekleyip 3 dakika fıkırdatın. Fasulyeyi süzüp durulayın, biraz suyla tencereye ekleyin ve tadı çekmesi için 15 dakika hafifçe pişirin. Birkaç taneyi tava kenarında ezip sosu kremamsı bir yahniye dönüştürün. Tuzla tatlandırın, fazla koyulaşırsa biraz su ekleyin. Sıcak, geleneksel olarak turşu ya da ekmekle servis edin.',
      it:'Scalda l’olio in una pentola e rosola la cipolla tritata fine a fuoco medio per circa 6 minuti, finché è morbida e ben dorata — una cipolla ben cotta è l’anima di questo piatto. Unisci l’aglio e la paprica e mescola 30 secondi, poi aggiungi la passata e l’alloro e lascia sobbollire 3 minuti. Scola e sciacqua i fagioli, aggiungili con un goccio d’acqua e fai sobbollire dolcemente 15 minuti perché prendano sapore. Schiaccia qualche fagiolo contro la pentola per addensare il sugo in uno stufato cremoso. Regola di sale e aggiungi un po’ d’acqua se diventa troppo denso. Servi caldo, tradizionalmente con sottaceti o pane.',
      ko:'냄비에 기름을 데우고 곱게 다진 양파를 중불에서 약 6분간 부드럽고 먹음직스러운 갈색이 될 때까지 볶는다 — 잘 볶은 양파가 이 요리의 핵심이다. 마늘과 파프리카 가루를 넣고 30초 볶은 뒤 토마토 퓌레와 월계수 잎을 넣어 3분간 보글보글 끓인다. 콩을 헹궈 물기를 빼고 물을 조금 넣어 15분간 은근히 끓여 맛이 배게 한다. 콩 몇 알을 냄비 벽에 눌러 으깨 소스를 걸쭉하고 크리미한 스튜로 만든다. 소금으로 간하고 너무 되직하면 물을 조금 넣는다. 따뜻하게, 전통적으로 피클이나 빵과 함께 낸다.' } },

  { id:'budget_004', name:NAMES.vinete, servings:2, prep:15, cook:30, costRon:4, nut:{cal:180,prot:3,carb:12,fat:14,fib:6}, tags:['budget','vegan','healthy'],
    ing:[ {q:500,u:'g',n:I.eggplant}, {q:1,n:I.onion}, {q:3,u:'tbsp',n:I.oil}, {q:1,n:I.lemon}, {n:I.salt} ],
    steps:{
      ro:'Înțeapă vinetele de câteva ori cu furculița și coace-le întregi — pe flacără, la grătar sau în cuptor încins — întorcându-le până coaja e arsă, iar miezul complet moale, circa 25-30 de minute. Lasă-le să se răcorească puțin, apoi curăță coaja arsă și scurge miezul într-o strecurătoare câteva minute, ca să piardă zeama amară. Toacă miezul fin cu un cuțit sau o lingură de lemn (evită vasele de metal, care îl înnegresc) până devine aproape pastă. Încorporează uleiul câte puțin, ca la maioneză, până se albește și devine cremos. Adaugă ceapa tăiată foarte mărunt, sărează și dă gust cu zeamă de lămâie. Servește rece, întinsă pe pâine.',
      en:'Prick the eggplants a few times with a fork and roast them whole — over an open flame, under the grill, or in a hot oven — turning until the skin is charred and the flesh is completely soft, about 25-30 minutes. Let them cool a little, then peel off the blackened skin and drain the flesh in a sieve for a few minutes to lose its bitter juices. Chop the flesh finely with a knife or wooden spoon (avoid metal bowls, which darken it) until it is almost a paste. Beat in the oil a little at a time, as if making mayonnaise, until it turns pale and creamy. Fold in the very finely chopped onion, season with salt, and sharpen with a squeeze of lemon. Serve cool, spread on bread.',
      es:'Pincha las berenjenas varias veces con un tenedor y ásalas enteras —sobre la llama, al grill o en el horno caliente— girándolas hasta que la piel esté quemada y la pulpa completamente blanda, unos 25-30 minutos. Deja que se templen, pela la piel ennegrecida y escurre la pulpa en un colador unos minutos para que pierda los jugos amargos. Pica la pulpa fina con cuchillo o cuchara de madera (evita recipientes de metal, que la oscurecen) hasta casi hacer una pasta. Incorpora el aceite poco a poco, como una mayonesa, hasta que aclare y quede cremosa. Añade la cebolla muy picada, sazona con sal y realza con un chorro de limón. Sirve fría, untada en pan.',
      fr:'Piquez les aubergines plusieurs fois à la fourchette et faites-les rôtir entières — sur une flamme, sous le gril ou au four chaud — en les retournant jusqu’à ce que la peau soit carbonisée et la chair complètement molle, environ 25-30 minutes. Laissez tiédir, retirez la peau noircie et laissez égoutter la chair dans une passoire quelques minutes pour perdre ses sucs amers. Hachez la chair finement au couteau ou à la cuillère en bois (évitez les récipients en métal, qui la noircissent) jusqu’à obtenir presque une pâte. Incorporez l’huile petit à petit, comme une mayonnaise, jusqu’à ce que ce soit pâle et crémeux. Ajoutez l’oignon très finement haché, salez et relevez d’un filet de citron. Servez frais, tartiné sur du pain.',
      de:'Die Auberginen mehrmals mit einer Gabel einstechen und im Ganzen rösten — über offener Flamme, unter dem Grill oder im heißen Ofen — dabei wenden, bis die Haut verkohlt und das Fruchtfleisch ganz weich ist, etwa 25-30 Minuten. Etwas abkühlen lassen, dann die verkohlte Haut abziehen und das Fruchtfleisch in einem Sieb einige Minuten abtropfen lassen, damit es die bitteren Säfte verliert. Das Fruchtfleisch mit Messer oder Holzlöffel fein hacken (Metallschüsseln vermeiden, sie verfärben es) bis fast eine Paste entsteht. Das Öl nach und nach einarbeiten, wie bei Mayonnaise, bis es hell und cremig wird. Die sehr fein gehackte Zwiebel unterheben, salzen und mit einem Spritzer Zitrone abrunden. Kühl servieren, auf Brot gestrichen.',
      pt:'Pique as beringelas várias vezes com um garfo e asse-as inteiras — sobre a chama, no grelhador ou no forno quente — virando até a pele ficar queimada e a polpa completamente mole, cerca de 25-30 minutos. Deixe amornar, retire a pele queimada e escorra a polpa num coador alguns minutos para perder os sucos amargos. Pique a polpa fina com faca ou colher de pau (evite recipientes de metal, que a escurecem) até quase virar pasta. Incorpore o óleo aos poucos, como numa maionese, até clarear e ficar cremosa. Envolva a cebola bem picada, tempere com sal e avive com um pouco de sumo de limão. Sirva fria, barrada em pão.',
      ru:'Наколите баклажаны вилкой в нескольких местах и запеките целиком — на открытом огне, под грилем или в горячей духовке — переворачивая, пока кожица не обуглится, а мякоть не станет совсем мягкой, около 25-30 минут. Дайте немного остыть, снимите обугленную кожицу и дайте мякоти стечь в сите несколько минут, чтобы ушёл горький сок. Мелко порубите мякоть ножом или деревянной ложкой (избегайте металлической посуды, она её темнит) почти до пасты. Вбивайте масло понемногу, как при приготовлении майонеза, пока масса не побледнеет и не станет кремовой. Вмешайте очень мелко нарезанный лук, посолите и оживите соком лимона. Подавайте охлаждённой, намазав на хлеб.',
      ar:'اثقب الباذنجان عدة مرات بالشوكة واشوِه كاملاً — على لهب مباشر أو تحت الشواية أو في فرن ساخن — مع تقليبه حتى تتفحّم القشرة ويصبح اللبّ طرياً تماماً، نحو 25-30 دقيقة. اتركه يبرد قليلاً، ثم قشّر القشرة المحروقة وصفّ اللبّ في مصفاة دقائق ليفقد عصارته المُرّة. افرم اللبّ ناعماً بسكين أو ملعقة خشب (تجنّب أوعية المعدن التي تسوّده) حتى يقارب العجينة. أضف الزيت تدريجياً كأنك تعدّ المايونيز حتى يشحب لونه ويصبح كريمياً. أضف البصل المفروم ناعماً جداً، ملّحه وأنعشه بعصير الليمون. قدّمه بارداً مدهوناً على الخبز.',
      zh:'用叉子在茄子上戳几下，整只烤制——明火、烤架或热烤箱皆可——不时翻面，直到表皮焦黑、内里完全软烂，约25-30分钟。稍微放凉，剥去焦皮，把茄肉放漏网里沥几分钟，去掉苦水。用刀或木勺把茄肉剁细（别用金属容器，会使其发黑），几乎成泥。像做蛋黄酱一样一点点加入油，搅打至发白绵滑。拌入切得极细的洋葱，加盐调味，挤入柠檬汁提味。冷食，抹在面包上。',
      ja:'なすをフォークで数か所刺し、丸ごと焼く——直火、グリル、または高温のオーブンで——皮が真っ黒に焦げて中が完全に柔らかくなるまで、約25〜30分返しながら焼く。少し冷ましてから焦げた皮をむき、ざるで数分水切りして苦い汁を落とす。金属のボウルは色が黒くなるので避け、包丁か木べらで果肉をほぼペースト状に細かく刻む。マヨネーズを作る要領で油を少しずつ加え、白っぽくクリーミーになるまで混ぜる。ごく細かく刻んだ玉ねぎを混ぜ込み、塩で味を調え、レモンを搾って引き締める。冷やして、パンに塗って供する。',
      hi:'बैंगन में काँटे से कुछ जगह छेद करें और साबुत भूनें — खुली आँच पर, ग्रिल में या गरम ओवन में — पलटते हुए जब तक छिलका जल जाए और गूदा पूरी तरह नरम हो, लगभग 25-30 मिनट। थोड़ा ठंडा होने दें, जला छिलका उतारें और गूदे को छलनी में कुछ मिनट रखकर उसका कड़वा रस निकलने दें। गूदे को चाकू या लकड़ी के चम्मच से बारीक काटें (धातु के बर्तन से बचें, वे इसे काला कर देते हैं) जब तक लगभग पेस्ट न बने। मेयोनेज़ की तरह थोड़ा-थोड़ा तेल फेंटते हुए मिलाएँ जब तक यह हल्का और मलाईदार हो जाए। बहुत बारीक कटा प्याज़ मिलाएँ, नमक डालें और नींबू निचोड़कर स्वाद बढ़ाएँ। ठंडा, ब्रेड पर लगाकर परोसें।',
      tr:'Patlıcanları çatalla birkaç yerinden delin ve bütün halde közleyin — açık ateşte, ızgarada ya da kızgın fırında — kabuğu kömürleşip içi tamamen yumuşayana dek çevirerek, yaklaşık 25-30 dakika. Biraz soğutun, yanmış kabuğu soyun ve eti bir süzgeçte birkaç dakika süzerek acı suyunu bırakmasını sağlayın. Eti bıçak ya da tahta kaşıkla (kararttığı için metal kaplardan kaçının) neredeyse macun olana dek ince ince doğrayın. Mayonez yapar gibi yağı azar azar ekleyip çırpın; rengi açılıp kremamsı olsun. Çok ince doğranmış soğanı katın, tuzla tatlandırın ve limon sıkarak canlandırın. Soğuk, ekmeğe sürerek servis edin.',
      it:'Bucherella le melanzane con una forchetta e arrostiscile intere — su fiamma viva, sotto il grill o in forno caldo — girandole finché la buccia è bruciacchiata e la polpa del tutto morbida, circa 25-30 minuti. Falle intiepidire, togli la buccia annerita e scola la polpa in un colino qualche minuto per perdere i succhi amari. Trita la polpa fine con coltello o cucchiaio di legno (evita recipienti di metallo, che la scuriscono) fin quasi a crema. Incorpora l’olio poco alla volta, come per una maionese, finché diventa pallida e cremosa. Unisci la cipolla tritata finissima, sala e ravviva con una spremuta di limone. Servi fresca, spalmata sul pane.',
      ko:'가지를 포크로 몇 군데 찌른 뒤 통째로 굽는다 — 직화, 그릴, 또는 뜨거운 오븐에서 — 껍질이 새까맣게 타고 속이 완전히 물러질 때까지 약 25~30분 뒤집어가며 굽는다. 살짝 식힌 뒤 탄 껍질을 벗기고 과육을 체에 몇 분간 밭쳐 쓴 즙을 뺀다. 금속 그릇은 색을 검게 하니 피하고, 칼이나 나무 주걱으로 과육을 거의 페이스트가 될 때까지 곱게 다진다. 마요네즈를 만들듯 기름을 조금씩 넣어 색이 연해지고 크리미해질 때까지 젓는다. 아주 곱게 다진 양파를 섞고 소금으로 간한 뒤 레몬을 짜 맛을 살린다. 차갑게, 빵에 발라 낸다.' } },

  { id:'budget_005', name:NAMES.ghiveci, servings:2, prep:20, cook:35, costRon:5, nut:{cal:260,prot:6,carb:38,fat:10,fib:9}, tags:['budget','vegan','healthy'],
    ing:[ {q:200,u:'g',n:I.potatoes}, {q:1,n:I.carrot}, {q:1,n:I.onion}, {q:1,n:I.bellPepper}, {q:200,u:'g',n:I.zucchini}, {q:200,u:'g',n:I.passata}, {q:2,u:'clove',n:I.garlic}, {q:3,u:'tbsp',n:I.oil}, {q:1,n:I.bayLeaf}, {n:I.salt} ],
    steps:{
      ro:'Taie toate legumele — cartof, morcov, ceapă, ardei gras și dovlecel — în bucăți de mărime asemănătoare, ca să se gătească uniform. Încălzește uleiul într-o oală largă și călește ceapa și usturoiul 4 minute, apoi adaugă legumele mai tari (cartof și morcov) și mai gătește 5 minute, amestecând. Adaugă ardeiul și dovlecelul, roșiile pasate, foaia de dafin și un praf bun de sare, împreună cu un strop de apă. Acoperă și fierbe blând circa 30 de minute, amestecând din când în când, până fiecare legumă e fragedă, iar sosul e bogat. Trebuie să iasă o tocană moale, nu o supă — dacă e nevoie, mai fierbe câteva minute descoperit. Potrivește de gust și servește cald, simplu sau ca garnitură.',
      en:'Cut all the vegetables — potato, carrot, onion, bell pepper and zucchini — into similar bite-sized pieces so they cook evenly. Warm the oil in a wide pot and soften the onion and garlic for 4 minutes, then add the harder vegetables (potato and carrot) and cook for 5 minutes, stirring. Add the pepper and zucchini, the tomato passata, bay leaf and a good pinch of salt, along with a splash of water. Cover and simmer gently for about 30 minutes, stirring occasionally, until every vegetable is tender and the sauce is rich. It should end up soft and stewy, not soupy — cook uncovered for the last few minutes if needed. Season to taste and serve warm, on its own or as a side.',
      es:'Corta todas las verduras —patata, zanahoria, cebolla, pimiento y calabacín— en trozos de tamaño similar para que cuezan por igual. Calienta el aceite en una olla amplia y sofríe la cebolla y el ajo 4 minutos, luego añade las verduras más duras (patata y zanahoria) y cocina 5 minutos, removiendo. Añade el pimiento y el calabacín, el tomate, la hoja de laurel y una buena pizca de sal, junto con un chorrito de agua. Tapa y cuece suave unos 30 minutos, removiendo de vez en cuando, hasta que todas las verduras estén tiernas y la salsa sea densa. Debe quedar como un guiso blando, no una sopa —cuece destapado los últimos minutos si hace falta—. Ajusta de sal y sirve caliente, solo o como guarnición.',
      fr:'Coupez tous les légumes — pomme de terre, carotte, oignon, poivron et courgette — en morceaux de taille similaire pour une cuisson homogène. Chauffez l’huile dans une grande casserole et faites revenir l’oignon et l’ail 4 minutes, puis ajoutez les légumes les plus fermes (pomme de terre et carotte) et faites cuire 5 minutes en remuant. Ajoutez le poivron et la courgette, les tomates passées, la feuille de laurier et une bonne pincée de sel, avec un peu d’eau. Couvrez et laissez mijoter doucement environ 30 minutes, en remuant de temps en temps, jusqu’à ce que chaque légume soit tendre et la sauce riche. Cela doit rester un ragoût moelleux, pas une soupe — cuisez à découvert les dernières minutes si besoin. Rectifiez l’assaisonnement et servez chaud, seul ou en accompagnement.',
      de:'Alle Gemüse — Kartoffel, Karotte, Zwiebel, Paprika und Zucchini — in ähnlich große Stücke schneiden, damit sie gleichmäßig garen. Das Öl in einem weiten Topf erwärmen und Zwiebel und Knoblauch 4 Minuten anschwitzen, dann das festere Gemüse (Kartoffel und Karotte) zugeben und unter Rühren 5 Minuten braten. Paprika und Zucchini, passierte Tomaten, Lorbeerblatt und eine gute Prise Salz zugeben, dazu einen Schuss Wasser. Zudecken und etwa 30 Minuten sanft köcheln, gelegentlich rühren, bis jedes Gemüse weich und die Soße reichhaltig ist. Es soll ein weicher Eintopf werden, keine Suppe — die letzten Minuten bei Bedarf offen kochen. Abschmecken und warm servieren, pur oder als Beilage.',
      pt:'Corte todos os legumes — batata, cenoura, cebola, pimentão e courgette — em pedaços de tamanho semelhante para cozerem por igual. Aqueça o óleo numa panela larga e refogue a cebola e o alho 4 minutos, depois junte os legumes mais duros (batata e cenoura) e cozinhe 5 minutos, mexendo. Junte o pimentão e a courgette, o tomate passata, a folha de louro e uma boa pitada de sal, com um pouco de água. Tape e cozinhe brandamente cerca de 30 minutos, mexendo de vez em quando, até todos os legumes ficarem macios e o molho encorpado. Deve ficar um guisado macio, não uma sopa — coza destapado nos últimos minutos se precisar. Acerte o sal e sirva quente, simples ou como acompanhamento.',
      ru:'Нарежьте все овощи — картофель, морковь, лук, болгарский перец и кабачок — кусочками схожего размера, чтобы они готовились равномерно. Разогрейте масло в широкой кастрюле и обжарьте лук и чеснок 4 минуты, затем добавьте более твёрдые овощи (картофель и морковь) и готовьте 5 минут, помешивая. Добавьте перец и кабачок, протёртые томаты, лавровый лист и хорошую щепотку соли, а также немного воды. Накройте и тушите на слабом огне около 30 минут, изредка помешивая, пока все овощи не станут мягкими, а соус — насыщенным. Должно получиться мягкое рагу, а не суп — при необходимости последние минуты готовьте без крышки. Посолите по вкусу и подавайте тёплым, само по себе или как гарнир.',
      ar:'قطّع كل الخضار — البطاطس والجزر والبصل والفلفل الحلو والكوسة — إلى قطع متقاربة الحجم لتنضج بالتساوي. سخّن الزيت في قدر واسع وشوّح البصل والثوم 4 دقائق، ثم أضف الخضار الأقسى (البطاطس والجزر) واطهها 5 دقائق مع التقليب. أضف الفلفل والكوسة والطماطم المهروسة وورقة الغار ورشة ملح جيدة مع رشة ماء. غطِّ القدر واطهه بهدوء نحو 30 دقيقة مع التقليب أحياناً حتى تنضج كل الخضار وتصبح الصلصة غنية. يجب أن يكون يخنة طرية لا شوربة — اطهه مكشوفاً في الدقائق الأخيرة إن لزم. اضبط التتبيل وقدّمه دافئاً، وحده أو كطبق جانبي.',
      zh:'把所有蔬菜——土豆、胡萝卜、洋葱、甜椒和西葫芦——切成大小相近的块，方便均匀成熟。宽口锅热油，炒洋葱和蒜4分钟，再加较硬的蔬菜（土豆和胡萝卜）翻炒5分钟。加入甜椒、西葫芦、番茄泥、香叶和一大撮盐，再加少许水。加盖小火煮约30分钟，其间不时搅动，至所有蔬菜软烂、汤汁浓郁。成品应是软糯的炖菜而非汤——需要的话最后几分钟开盖收汁。按口味调味，趁热单吃或作配菜。',
      ja:'すべての野菜——じゃがいも、にんじん、玉ねぎ、パプリカ、ズッキーニ——を火通りがそろうよう同じくらいの一口大に切る。広めの鍋に油を温め、玉ねぎとにんにくを4分炒め、火の通りにくい野菜（じゃがいもとにんじん）を加えて混ぜながら5分炒める。パプリカとズッキーニ、トマトピューレ、ローリエ、塩ひとつまみを水少々とともに加える。ふたをして約30分、時々混ぜながら、すべての野菜が柔らかくソースが濃厚になるまで静かに煮る。スープではなく、柔らかい煮込みに仕上げる——必要なら最後の数分はふたを取って煮詰める。味を調え、そのまま、または付け合わせとして温かいうちに供する。',
      hi:'सभी सब्ज़ियाँ — आलू, गाजर, प्याज़, शिमला मिर्च और तोरी — एक जैसे टुकड़ों में काटें ताकि समान रूप से पकें। चौड़े बर्तन में तेल गरम करें और प्याज़ व लहसुन 4 मिनट भूनें, फिर सख्त सब्ज़ियाँ (आलू और गाजर) डालकर 5 मिनट चलाते हुए पकाएँ। शिमला मिर्च और तोरी, टमाटर प्यूरी, तेज पत्ता और अच्छी चुटकी नमक थोड़े पानी के साथ डालें। ढककर लगभग 30 मिनट धीमी आँच पर बीच-बीच में चलाते हुए पकाएँ जब तक हर सब्ज़ी नरम और सॉस गाढ़ी हो। यह नरम सालन जैसा बने, सूप नहीं — ज़रूरत हो तो आख़िरी कुछ मिनट खुला पकाएँ। स्वादानुसार नमक ठीक करें और गरम, अकेले या साइड के रूप में परोसें।',
      tr:'Bütün sebzeleri — patates, havuç, soğan, dolmalık biber ve kabak — eşit pişsin diye benzer büyüklükte lokmalara doğrayın. Geniş bir tencerede yağı ısıtın, soğan ve sarımsağı 4 dakika kavurun, sonra sert sebzeleri (patates ve havuç) ekleyip karıştırarak 5 dakika pişirin. Biber ve kabağı, domates püresini, defne yaprağını ve iyi bir tutam tuzu biraz suyla ekleyin. Kapağını kapatıp yaklaşık 30 dakika, ara sıra karıştırarak, tüm sebzeler yumuşayıp sos koyulaşana dek hafifçe pişirin. Çorba değil, yumuşak bir güveç olmalı — gerekirse son birkaç dakika kapaksız pişirin. Tuzunu ayarlayıp sıcak, tek başına ya da garnitür olarak servis edin.',
      it:'Taglia tutte le verdure — patata, carota, cipolla, peperone e zucchina — a pezzi di dimensioni simili così cuociono in modo uniforme. Scalda l’olio in una pentola ampia e fai appassire cipolla e aglio per 4 minuti, poi aggiungi le verdure più dure (patata e carota) e cuoci 5 minuti, mescolando. Aggiungi peperone e zucchina, la passata, l’alloro e una buona presa di sale, con un goccio d’acqua. Copri e fai sobbollire dolcemente circa 30 minuti, mescolando ogni tanto, finché ogni verdura è tenera e il sugo è ricco. Deve venire uno stufato morbido, non una minestra — cuoci scoperto gli ultimi minuti se serve. Regola di sale e servi caldo, da solo o come contorno.',
      ko:'모든 채소 — 감자, 당근, 양파, 파프리카, 애호박 — 를 고르게 익도록 비슷한 한입 크기로 썬다. 넓은 냄비에 기름을 데우고 양파와 마늘을 4분 볶은 뒤 단단한 채소(감자와 당근)를 넣어 저으며 5분 볶는다. 파프리카와 애호박, 토마토 퓌레, 월계수 잎, 소금 넉넉히 한 꼬집을 물 조금과 함께 넣는다. 뚜껑을 덮고 약 30분간 가끔 저으며 모든 채소가 부드럽고 소스가 진해질 때까지 은근히 끓인다. 수프가 아니라 부드러운 스튜가 되어야 한다 — 필요하면 마지막 몇 분은 뚜껑을 열고 졸인다. 간을 맞춰 그대로 또는 곁들임으로 따뜻하게 낸다.' } },
  { id:'budget_006', name:NAMES.fasoleBatuta, servings:2, prep:10, cook:60, costRon:4, nut:{cal:380,prot:18,carb:45,fat:14,fib:15}, tags:['budget','vegan','high-protein'],
    ing:[ {q:250,u:'g',n:I.whiteBeans}, {q:2,n:I.onion}, {q:4,u:'tbsp',n:I.oil}, {q:1,u:'tsp',n:I.paprika}, {n:I.salt} ],
    steps:{
      ro:'Dacă folosești fasole uscată, las-o peste noapte în apă rece, apoi fierbe-o în apă proaspătă circa o oră, până e foarte moale; scurge-o, păstrând puțin din zeamă. Pasează fasolea caldă cu 2 linguri de ulei (un blender o face mai fină) până devine cremoasă, subțiind cu un strop de zeamă, și potrivește bine de sare. Taie ceapa solzișori și călește-o încet în restul de ulei până se rumenește frumos și se îndulcește, circa 10 minute, apoi ia de pe foc și amestecă boiaua. Întinde pasta de fasole pe o farfurie și pune deasupra ceapa caldă cu boia. Servește la temperatura camerei, cu pâine și murături.',
      en:'If using dried beans, soak them overnight in cold water, then boil in fresh water for about an hour until very soft; drain, keeping a little of the liquid. Mash the warm beans with 2 tablespoons of the oil (a blender makes it smoother) until creamy, loosening with a splash of the liquid, and season well with salt. Slice the onions thinly and fry them slowly in the remaining oil until deep golden and sweet, about 10 minutes, then take off the heat and stir in the paprika. Spread the bean paste on a plate and top with the warm paprika onions. Serve at room temperature with bread and pickles.',
      es:'Si usas alubias secas, remójalas toda la noche y cuécelas en agua limpia una hora hasta que estén muy blandas; escurre reservando un poco del líquido. Tritura las alubias calientes con 2 cucharadas de aceite (la batidora las deja más finas) hasta que estén cremosas, aflojando con un poco del líquido, y sazona bien con sal. Corta las cebollas en juliana fina y fríelas despacio en el aceite restante hasta que estén doradas y dulces, unos 10 minutos, retira del fuego y añade el pimentón. Extiende el puré en un plato y cúbrelo con la cebolla caliente al pimentón. Sirve a temperatura ambiente con pan y encurtidos.',
      fr:'Si vous utilisez des haricots secs, faites-les tremper une nuit, puis cuire à l’eau fraîche environ une heure jusqu’à ce qu’ils soient très tendres ; égouttez en gardant un peu d’eau. Écrasez les haricots chauds avec 2 c. à s. d’huile (un mixeur les rend plus lisses) jusqu’à consistance crémeuse, en détendant avec un peu d’eau, et salez bien. Émincez finement les oignons et faites-les revenir lentement dans le reste d’huile jusqu’à ce qu’ils soient bien dorés et doux, environ 10 minutes, retirez du feu et ajoutez le paprika. Étalez la purée dans une assiette et couvrez des oignons chauds au paprika. Servez à température ambiante avec du pain et des pickles.',
      de:'Bei getrockneten Bohnen diese über Nacht einweichen und in frischem Wasser etwa eine Stunde weich kochen; abgießen, etwas Kochwasser aufbewahren. Die warmen Bohnen mit 2 EL Öl (ein Mixer macht es feiner) cremig pürieren, mit etwas Wasser lockern und kräftig salzen. Die Zwiebeln fein schneiden und im restlichen Öl langsam goldbraun und süßlich braten, etwa 10 Minuten, vom Herd nehmen und das Paprikapulver einrühren. Die Bohnenpaste auf einen Teller streichen und mit den warmen Paprika-Zwiebeln belegen. Bei Zimmertemperatur mit Brot und Eingelegtem servieren.',
      pt:'Se usar feijão seco, demolhe-o de um dia para o outro e coza em água fresca cerca de uma hora até ficar muito macio; escorra, guardando um pouco da água. Esmague o feijão quente com 2 colheres de sopa de óleo (a varinha deixa-o mais fino) até ficar cremoso, soltando com um pouco da água, e tempere bem com sal. Corte as cebolas fininhas e frite-as devagar no restante óleo até ficarem bem douradas e doces, cerca de 10 minutos, retire do lume e junte o colorau. Espalhe o puré num prato e cubra com as cebolas quentes ao colorau. Sirva à temperatura ambiente com pão e picles.',
      ru:'Если используете сухую фасоль, замочите её на ночь и отварите в свежей воде около часа до мягкости; слейте, сохранив немного отвара. Разомните тёплую фасоль с 2 столовыми ложками масла (блендер сделает нежнее) до кремовой массы, разбавьте отваром и хорошо посолите. Нарежьте лук тонко и медленно обжарьте в оставшемся масле до золотистости и сладости, около 10 минут, снимите с огня и вмешайте паприку. Намажьте фасолевую пасту на тарелку и выложите сверху тёплый лук с паприкой. Подавайте комнатной температуры с хлебом и соленьями.',
      ar:'إن استخدمت فاصوليا جافة، انقعها ليلة كاملة ثم اسلقها في ماء جديد نحو ساعة حتى تلين تماماً؛ صفّها واحتفظ بقليل من الماء. اهرس الفاصوليا الدافئة مع ملعقتين كبيرتين من الزيت (الخلاط يجعلها أنعم) حتى تصبح كريمية، وخفّفها برشة ماء وملّحها جيداً. قطّع البصل شرائح رفيعة وشوّحه ببطء في باقي الزيت حتى يذهبّ ويحلو، نحو 10 دقائق، ارفعه عن النار وأضف البابريكا. افرد معجون الفاصوليا في طبق وغطّه بالبصل الدافئ بالبابريكا. قدّمه بحرارة الغرفة مع الخبز والمخللات.',
      zh:'若用干豆，提前一夜泡软，再用清水煮约1小时至非常软烂；沥干，留少许煮豆水。趁热用2大勺油把豆子压成泥（用搅拌机更细腻），加少许煮豆水调稀，加盐充分调味。洋葱切细丝，用余下的油小火慢炒至金黄回甜，约10分钟，离火拌入红椒粉。把豆泥抹在盘中，铺上温热的红椒洋葱。常温食用，配面包和腌菜。',
      ja:'乾燥豆を使う場合は一晩浸し、新しい水で約1時間、とても柔らかくなるまで茹でる；ゆで汁を少し取り分けて水を切る。温かい豆を油大さじ2とともにクリーミーになるまでつぶし（ブレンダーだと滑らか）、ゆで汁でゆるめて塩でしっかり味付けする。玉ねぎを薄切りにし、残りの油でしっかり色づいて甘くなるまで約10分弱火で炒め、火を止めてパプリカを混ぜる。豆のペーストを皿に広げ、温かいパプリカ玉ねぎをのせる。常温で、パンやピクルスを添えて供する。',
      hi:'सूखी बीन्स इस्तेमाल करें तो रातभर भिगोकर ताज़े पानी में लगभग एक घंटा बहुत नरम होने तक उबालें; छानकर थोड़ा पानी बचा लें। गरम बीन्स को 2 बड़े चम्मच तेल के साथ मलाईदार होने तक मैश करें (ब्लेंडर से महीन बनती है), थोड़े पानी से पतला करें और नमक अच्छे से डालें। प्याज़ को पतला काटें और बचे तेल में धीमी आँच पर सुनहरा-मीठा होने तक लगभग 10 मिनट भूनें, आँच से उतारकर पेपरिका मिलाएँ। बीन स्प्रेड को प्लेट पर फैलाएँ और ऊपर गरम पेपरिका-प्याज़ डालें। कमरे के तापमान पर ब्रेड और अचार के साथ परोसें।',
      tr:'Kuru fasulye kullanıyorsanız gece boyu ıslatıp taze suda yaklaşık bir saat, iyice yumuşayana dek haşlayın; suyundan biraz ayırıp süzün. Sıcak fasulyeyi 2 yemek kaşığı yağla (blender daha pürüzsüz yapar) kremamsı olana dek ezin, biraz suyla açın ve iyice tuzlayın. Soğanları ince doğrayıp kalan yağda ağır ağır iyice kızarıp tatlanana dek yaklaşık 10 dakika kavurun, ateşten alıp toz biberi karıştırın. Fasulye ezmesini tabağa yayıp üzerine sıcak biberli soğanı koyun. Oda sıcaklığında ekmek ve turşuyla servis edin.',
      it:'Se usi fagioli secchi, mettili in ammollo una notte e lessali in acqua fresca circa un’ora finché sono morbidissimi; scola tenendo un po’ di liquido. Schiaccia i fagioli caldi con 2 cucchiai d’olio (il frullatore li rende più lisci) fino a crema, allunga con un po’ di liquido e sala bene. Affetta le cipolle sottili e falle rosolare piano nell’olio rimasto finché sono ben dorate e dolci, circa 10 minuti, togli dal fuoco e unisci la paprica. Spalma il purè su un piatto e completa con le cipolle calde alla paprica. Servi a temperatura ambiente con pane e sottaceti.',
      ko:'말린 콩을 쓰면 하룻밤 불려 새 물에 약 1시간, 아주 부드러워질 때까지 삶고 삶은 물을 조금 남겨 물기를 뺀다. 따뜻한 콩을 기름 2큰술과 함께 크리미해질 때까지 으깨고(블렌더를 쓰면 더 곱다) 삶은 물로 농도를 맞춘 뒤 소금으로 충분히 간한다. 양파를 얇게 썰어 남은 기름에 약불로 진한 갈색이 나고 단맛이 날 때까지 약 10분 볶고, 불을 끈 뒤 파프리카 가루를 섞는다. 콩 스프레드를 접시에 펴고 따뜻한 파프리카 양파를 올린다. 실온으로, 빵과 피클을 곁들여 낸다.' } },

  { id:'budget_007', name:NAMES.mamaliga, servings:2, prep:5, cook:25, costRon:5, nut:{cal:420,prot:14,carb:60,fat:15,fib:5}, tags:['budget','vegetarian','family'],
    ing:[ {q:150,u:'g',n:I.cornmeal}, {q:750,u:'ml',n:I.water}, {q:100,u:'g',n:I.cheese}, {q:100,u:'g',n:I.sourCream}, {n:I.salt} ],
    steps:{
      ro:'Adu apa cu sare la fiert și toarnă mălaiul în ploaie, amestecând viguros ca să nu se formeze cocoloașe. Fierbe la foc mic, amestecând des cu o lingură de lemn, circa 20 de minute, până se îngroașă și devine netedă. Pune jumătate în boluri, sfărâmă deasupra jumătate din brânză, apoi adaugă restul de mămăligă și brânza rămasă, ca să se topească între straturile calde. Pune peste fiecare bol o lingură generoasă de smântână. Servește fierbinte, cât brânza e încă moale.',
      en:'Bring the salted water to a boil and rain in the cornmeal, whisking hard to keep it lump-free. Cook on low, stirring often with a wooden spoon, for about 20 minutes until thick and smooth. Spoon half into bowls, crumble over half the cheese, then add the rest of the polenta and the remaining cheese so it melts between the warm layers. Top each bowl with a generous spoon of sour cream. Serve hot, while the cheese is still soft.',
      es:'Lleva el agua con sal a ebullición y vierte la harina de maíz en un hilo, batiendo fuerte para evitar grumos. Cocina a fuego bajo, removiendo a menudo con cuchara de madera, unos 20 minutos hasta que espese y quede suave. Pon la mitad en boles, desmenuza encima la mitad del queso, luego añade el resto de la polenta y el queso restante para que se funda entre las capas calientes. Corona cada bol con una buena cucharada de crema agria. Sirve caliente, mientras el queso siga blando.',
      fr:'Portez l’eau salée à ébullition et versez la semoule de maïs en pluie, en fouettant fort pour éviter les grumeaux. Faites cuire à feu doux, en remuant souvent à la cuillère en bois, environ 20 minutes jusqu’à ce que ce soit épais et lisse. Répartissez la moitié dans des bols, émiettez dessus la moitié du fromage, puis ajoutez le reste de polenta et le reste de fromage pour qu’il fonde entre les couches chaudes. Couronnez chaque bol d’une belle cuillerée de crème aigre. Servez chaud, tant que le fromage est encore moelleux.',
      de:'Das Salzwasser zum Kochen bringen und den Maisgrieß einrieseln lassen, dabei kräftig rühren, damit keine Klümpchen entstehen. Bei niedriger Hitze unter häufigem Rühren mit einem Holzlöffel etwa 20 Minuten dick und glatt kochen. Die Hälfte in Schalen geben, die Hälfte des Käses darüberbröseln, dann die restliche Polenta und den restlichen Käse zugeben, damit er zwischen den warmen Schichten schmilzt. Jede Schale mit einem großzügigen Löffel Schmand krönen. Heiß servieren, solange der Käse noch weich ist.',
      pt:'Leve a água com sal a ferver e deite o fubá em fio, batendo com força para evitar grumos. Cozinhe em lume baixo, mexendo com frequência com colher de pau, cerca de 20 minutos até engrossar e ficar liso. Coloque metade em taças, esfarele por cima metade do queijo, depois junte o resto da polenta e o queijo restante para derreter entre as camadas quentes. Cubra cada taça com uma boa colher de natas azedas. Sirva quente, enquanto o queijo ainda está mole.',
      ru:'Доведите подсолённую воду до кипения и всыпьте кукурузную крупу тонкой струйкой, энергично взбивая, чтобы не было комков. Варите на слабом огне, часто помешивая деревянной ложкой, около 20 минут до густоты и гладкости. Выложите половину в миски, раскрошите сверху половину брынзы, затем добавьте остальную поленту и оставшуюся брынзу, чтобы она расплавилась между тёплыми слоями. Увенчайте каждую миску щедрой ложкой сметаны. Подавайте горячим, пока брынза ещё мягкая.',
      ar:'اغلِ الماء المملّح وأضف دقيق الذرة تدريجياً مع الخفق القوي لتجنّب التكتل. اطهه على نار هادئة مع التحريك المتكرر بملعقة خشب نحو 20 دقيقة حتى يثخن ويصبح ناعماً. ضع النصف في أوعية، فتّت فوقه نصف الجبن، ثم أضف باقي البولنتا والجبن المتبقي ليذوب بين الطبقات الدافئة. توّج كل وعاء بملعقة سخية من القشدة الحامضة. قدّمه ساخناً والجبن ما زال طرياً.',
      zh:'把盐水烧开，玉米粉呈细流状缓缓倒入，用力搅打以免结块。小火边煮边用木勺常搅约20分钟，至浓稠顺滑。先盛一半到碗里，撒上一半奶酪碎，再加入剩下的玉米粥和剩余奶酪，让奶酪在温热的两层间融化。每碗顶上放一大勺酸奶油。趁热、奶酪还软时食用。',
      ja:'塩水を沸かし、コーンミールを細く流し入れながら、だまにならないよう力強く混ぜる。弱火で木べらでよく混ぜながら約20分、とろりと滑らかになるまで煮る。半量を器に盛り、チーズの半量を崩してのせ、残りのポレンタと残りのチーズを重ねて温かい層の間で溶かす。各器にサワークリームをたっぷり一さじのせる。チーズが柔らかいうちに熱々で供する。',
      hi:'नमकीन पानी उबालें और मक्के का आटा धार बनाकर डालते हुए ज़ोर से फेंटें ताकि गुठलियाँ न बनें। धीमी आँच पर लकड़ी के चम्मच से बार-बार चलाते हुए लगभग 20 मिनट गाढ़ा और चिकना होने तक पकाएँ। आधा हिस्सा कटोरों में डालें, ऊपर आधी चीज़ चूरा करें, फिर बची पोलेंटा और बची चीज़ डालें ताकि गरम परतों के बीच पिघल जाए। हर कटोरे पर एक भरपूर चम्मच खट्टी क्रीम डालें। गरमागरम, चीज़ के नरम रहते ही परोसें।',
      tr:'Tuzlu suyu kaynatın ve mısır ununu ince ince dökerek topaklanmasın diye kuvvetlice çırpın. Kısık ateşte tahta kaşıkla sık karıştırarak yaklaşık 20 dakika koyulaşıp pürüzsüz olana dek pişirin. Yarısını kâselere alın, üzerine peynirin yarısını ufalayın, sonra kalan lapayı ve kalan peyniri ekleyin ki sıcak katlar arasında erisin. Her kâseyi bol bir kaşık ekşi krema ile taçlandırın. Peynir hâlâ yumuşakken sıcak servis edin.',
      it:'Porta a bollore l’acqua salata e versa la farina di mais a pioggia, frustando con forza per evitare grumi. Cuoci a fuoco basso, mescolando spesso con un cucchiaio di legno, per circa 20 minuti finché è densa e liscia. Metti metà nelle ciotole, sbriciola sopra metà del formaggio, poi aggiungi il resto della polenta e il formaggio rimasto perché fonda tra gli strati caldi. Corona ogni ciotola con una generosa cucchiaiata di panna acida. Servi calda, finché il formaggio è ancora morbido.',
      ko:'소금물을 끓이고 옥수수가루를 가늘게 흘려 넣으며 덩어리지지 않게 세게 저어준다. 약불에서 나무 주걱으로 자주 저으며 약 20분간 되직하고 매끈해질 때까지 끓인다. 절반을 그릇에 담고 치즈 절반을 부숴 올린 뒤, 남은 폴렌타와 남은 치즈를 더해 따뜻한 층 사이에서 녹게 한다. 각 그릇에 사워크림을 넉넉히 한 숟갈 올린다. 치즈가 부드러울 때 뜨겁게 낸다.' } },

  { id:'budget_008', name:NAMES.ardei, servings:2, prep:20, cook:45, costRon:5, nut:{cal:340,prot:7,carb:55,fat:11,fib:7}, tags:['budget','vegan','family'],
    ing:[ {q:4,n:I.bellPepper}, {q:120,u:'g',n:I.rice}, {q:1,n:I.onion}, {q:1,n:I.carrot}, {q:200,u:'g',n:I.passata}, {q:3,u:'tbsp',n:I.oil}, {n:I.salt} ],
    steps:{
      ro:'Taie capacele ardeilor și scoate semințele. Călește ceapa tocată și morcovul ras în ulei 5 minute, apoi adaugă orezul clătit și mai gătește 2 minute; potrivește de sare. Umple ardeii lejer cu compoziția de orez, fiindcă se umflă la fiert, și așază-i în picioare într-o oală. Toarnă roșiile pasate în jurul lor cu apă cât să-i acopere aproape complet și fierbe blând, acoperit, circa 40 de minute, până ardeii sunt fragezi și orezul e fiert. Stropește-i o dată-de două ori cu sos și servește cald, cu sosul turnat deasupra.',
      en:'Cut the tops off the peppers and scoop out the seeds. Soften the chopped onion and grated carrot in the oil for 5 minutes, then stir in the rinsed rice and cook for 2 minutes; season with salt. Fill the peppers loosely with the rice mixture, since it swells as it cooks, and stand them upright in a pot. Pour the tomato passata around them with enough water to nearly cover, and simmer gently, covered, for about 40 minutes until the peppers are tender and the rice is done. Baste once or twice, and serve warm with the sauce spooned over.',
      es:'Corta la parte superior de los pimientos y retira las semillas. Sofríe la cebolla picada y la zanahoria rallada en el aceite 5 minutos, añade el arroz enjuagado y cocina 2 minutos; sazona con sal. Rellena los pimientos sin apretar, porque el arroz crece al cocer, y colócalos de pie en una olla. Vierte el tomate alrededor con agua hasta casi cubrirlos y cuece tapado a fuego suave unos 40 minutos, hasta que estén tiernos y el arroz cocido. Riega una o dos veces con la salsa y sirve caliente con la salsa por encima.',
      fr:'Coupez le chapeau des poivrons et retirez les graines. Faites revenir l’oignon haché et la carotte râpée dans l’huile 5 minutes, ajoutez le riz rincé et faites cuire 2 minutes ; salez. Remplissez les poivrons sans tasser, car le riz gonfle à la cuisson, et posez-les debout dans une casserole. Versez les tomates passées autour avec de l’eau pour les couvrir presque, et laissez mijoter à couvert à feu doux environ 40 minutes jusqu’à ce que les poivrons soient tendres et le riz cuit. Arrosez une ou deux fois de sauce et servez chaud, nappé de sauce.',
      de:'Von den Paprika die Deckel abschneiden und die Kerne entfernen. Zwiebel gehackt und Karotte gerieben im Öl 5 Minuten anschwitzen, den abgespülten Reis zugeben und 2 Minuten mitkochen; salzen. Die Paprika locker mit der Reismischung füllen, da der Reis beim Garen aufquillt, und aufrecht in einen Topf stellen. Die passierten Tomaten mit so viel Wasser darum gießen, dass sie fast bedeckt sind, und zugedeckt bei niedriger Hitze etwa 40 Minuten köcheln, bis die Paprika weich und der Reis gar ist. Ein- bis zweimal mit Soße übergießen und warm servieren, mit Soße darüber.',
      pt:'Corte a tampa dos pimentos e retire as sementes. Refogue a cebola picada e a cenoura ralada no óleo 5 minutos, junte o arroz lavado e cozinhe 2 minutos; tempere com sal. Recheie os pimentos sem apertar, pois o arroz incha ao cozer, e ponha-os em pé numa panela. Deite o tomate passata à volta com água quase a cobrir e cozinhe tapado em lume brando cerca de 40 minutos, até os pimentos ficarem macios e o arroz cozido. Regue uma ou duas vezes com o molho e sirva quente, com o molho por cima.',
      ru:'Срежьте у перцев верхушки и удалите семена. Обжарьте нарезанный лук и тёртую морковь в масле 5 минут, добавьте промытый рис и готовьте 2 минуты; посолите. Наполните перцы неплотно, так как рис разбухает, и поставьте их вертикально в кастрюлю. Влейте вокруг протёртые томаты с водой почти до покрытия и тушите под крышкой на слабом огне около 40 минут, пока перцы не станут мягкими, а рис готовым. Полейте раз-другой соусом и подавайте тёплыми, полив соусом.',
      ar:'اقطع رؤوس الفلفل وأخرج البذور. شوّح البصل المفروم والجزر المبشور في الزيت 5 دقائق، أضف الأرز المغسول واطهه دقيقتين؛ ملّح. احشُ الفلفل بارتخاء لأن الأرز ينتفخ عند الطهي، وارصّه واقفاً في قدر. اسكب الطماطم المهروسة حوله مع ماء يكاد يغمره واطهه مغطى على نار هادئة نحو 40 دقيقة حتى يلين الفلفل وينضج الأرز. اسقِه بالصلصة مرة أو مرتين وقدّمه دافئاً مع الصلصة فوقه.',
      zh:'切下甜椒顶盖，去籽。用油炒切碎的洋葱和擦丝的胡萝卜5分钟，加入洗好的米再炒2分钟，加盐调味。把米馅松松地填入甜椒（米受热会膨胀），竖着码进锅中。四周倒入番茄泥并加水至几乎没过，加盖小火炖约40分钟，至甜椒软、米熟。中途浇一两次汤汁，趁热连汤汁一起上桌。',
      ja:'ピーマンの上部を切り取り、種を除く。みじん切りの玉ねぎとすりおろしたにんじんを油で5分炒め、洗った米を加えて2分炒める；塩で味付けする。米は煮ると膨らむのでゆるめに詰め、鍋に立てて並べる。周りにトマトピューレを注ぎ、ほぼかぶるまで水を足し、ふたをして弱火で約40分、ピーマンが柔らかく米が炊けるまで煮る。途中で1〜2回ソースをかけ、ソースをかけて温かいうちに供する。',
      hi:'शिमला मिर्च के ऊपरी हिस्से काटकर बीज निकालें। कटा प्याज़ और कद्दूकस गाजर तेल में 5 मिनट भूनें, धुला चावल डालकर 2 मिनट पकाएँ; नमक डालें। मिर्च को ढीला भरें क्योंकि चावल पकते समय फूलता है, और बर्तन में खड़ा रखें। चारों ओर टमाटर प्यूरी डालें और लगभग ढकने तक पानी डालें, ढककर धीमी आँच पर लगभग 40 मिनट पकाएँ जब तक मिर्च नरम और चावल पक जाए। एक-दो बार सॉस से सींचें और ऊपर सॉस डालकर गरम परोसें।',
      tr:'Biberlerin kapaklarını kesip çekirdeklerini çıkarın. Doğranmış soğan ve rendelenmiş havucu yağda 5 dakika kavurun, yıkanmış pirinci ekleyip 2 dakika pişirin; tuzlayın. Pirinç pişerken şişeceği için biberleri gevşek doldurun ve tencerede dik dizin. Etraflarına domates püresini dökün, neredeyse örtene kadar su ekleyin ve kapağı kapalı kısık ateşte yaklaşık 40 dakika, biberler yumuşayıp pirinç pişene dek pişirin. Bir iki kez sosla gezdirin ve üzerine sos dökerek sıcak servis edin.',
      it:'Taglia la calotta ai peperoni e togli i semi. Fai appassire cipolla tritata e carota grattugiata nell’olio per 5 minuti, unisci il riso sciacquato e cuoci 2 minuti; sala. Riempi i peperoni senza pressare, perché il riso gonfia in cottura, e mettili in piedi in una pentola. Versa intorno la passata con acqua quasi a coprirli e fai sobbollire coperto a fuoco basso circa 40 minuti, finché i peperoni sono teneri e il riso cotto. Bagnali una o due volte col sugo e servi caldi, col sugo sopra.',
      ko:'파프리카 윗부분을 잘라내고 씨를 제거한다. 다진 양파와 채 썬 당근을 기름에 5분 볶고 헹군 쌀을 넣어 2분 볶은 뒤 소금으로 간한다. 쌀은 익으며 부푸니 느슨하게 채우고 냄비에 세워 담는다. 주위에 토마토 퓌레를 붓고 거의 잠길 만큼 물을 더해 뚜껑을 덮고 약불에서 약 40분, 파프리카가 부드럽고 쌀이 익을 때까지 끓인다. 한두 번 소스를 끼얹고 소스를 위에 부어 따뜻하게 낸다.' } },

  { id:'budget_009', name:NAMES.zacusca, servings:2, prep:25, cook:60, costRon:4, nut:{cal:220,prot:3,carb:16,fat:16,fib:6}, tags:['budget','vegan','healthy'],
    ing:[ {q:400,u:'g',n:I.eggplant}, {q:3,n:I.bellPepper}, {q:2,n:I.onion}, {q:150,u:'g',n:I.passata}, {q:5,u:'tbsp',n:I.oil}, {q:1,n:I.bayLeaf}, {n:I.salt} ],
    steps:{
      ro:'Coace vinetele și ardeii întregi până coaja se arde și miezul se înmoaie, circa 30 de minute, apoi curăță-i și toacă-i mărunt. Călește ceapa tocată în ulei la foc mic până se înmoaie și se rumenește, circa 10 minute. Adaugă legumele coapte, roșiile pasate și foaia de dafin și gătește blând, amestecând des ca să nu se prindă, circa 40 de minute, până se închide la culoare, se îngroașă și uleiul iese deasupra. Potrivește de sare și scoate foaia de dafin. Servește rece, întinsă gros pe pâine — se ține câteva zile la frigider.',
      en:'Roast the eggplants and peppers whole until their skins char and the flesh softens, about 30 minutes, then peel and chop them finely. Fry the chopped onion in the oil over low heat until soft and golden, about 10 minutes. Add the roasted vegetables, the tomato passata and the bay leaf, and cook gently, stirring often so it doesn’t catch, for about 40 minutes until it darkens, thickens, and the oil rises to the top. Season with salt to taste and discard the bay leaf. Serve cool, spread thickly on bread — it keeps for days in the fridge.',
      es:'Asa las berenjenas y los pimientos enteros hasta que la piel se queme y la pulpa se ablande, unos 30 minutos, pélalos y pícalos fino. Sofríe la cebolla picada en el aceite a fuego bajo hasta que esté blanda y dorada, unos 10 minutos. Añade las verduras asadas, el tomate y la hoja de laurel y cocina suave, removiendo a menudo para que no se pegue, unos 40 minutos hasta que oscurezca, espese y el aceite suba a la superficie. Sazona con sal y retira el laurel. Sirve fría, untada gruesa en pan — se conserva días en la nevera.',
      fr:'Faites rôtir les aubergines et poivrons entiers jusqu’à ce que la peau soit carbonisée et la chair molle, environ 30 minutes, puis pelez-les et hachez-les finement. Faites revenir l’oignon haché dans l’huile à feu doux jusqu’à ce qu’il soit tendre et doré, environ 10 minutes. Ajoutez les légumes rôtis, les tomates passées et la feuille de laurier et faites cuire doucement, en remuant souvent pour que ça n’attache pas, environ 40 minutes jusqu’à ce que ça fonce, épaississe et que l’huile remonte. Salez et retirez le laurier. Servez froid, tartiné épais sur du pain — se garde plusieurs jours au frais.',
      de:'Auberginen und Paprika im Ganzen rösten, bis die Haut verkohlt und das Fruchtfleisch weich ist, etwa 30 Minuten, dann schälen und fein hacken. Die gehackte Zwiebel im Öl bei niedriger Hitze weich und goldbraun braten, etwa 10 Minuten. Das geröstete Gemüse, die passierten Tomaten und das Lorbeerblatt zugeben und sanft köcheln, oft rühren, damit nichts ansetzt, etwa 40 Minuten, bis es dunkler und dicker wird und das Öl obenauf steigt. Mit Salz abschmecken und das Lorbeerblatt entfernen. Kühl servieren, dick aufs Brot gestrichen — hält sich tagelang im Kühlschrank.',
      pt:'Asse as beringelas e os pimentos inteiros até a pele queimar e a polpa amolecer, cerca de 30 minutos, depois descasque e pique fino. Refogue a cebola picada no óleo em lume baixo até ficar macia e dourada, cerca de 10 minutos. Junte os legumes assados, o tomate passata e a folha de louro e cozinhe devagar, mexendo com frequência para não pegar, cerca de 40 minutos até escurecer, engrossar e o óleo subir. Tempere com sal e retire o louro. Sirva fria, barrada grossa no pão — dura dias no frigorífico.',
      ru:'Запеките баклажаны и перцы целиком, пока кожица не обуглится, а мякоть не станет мягкой, около 30 минут, затем очистите и мелко нарежьте. Обжарьте нарезанный лук в масле на слабом огне до мягкости и золотистости, около 10 минут. Добавьте запечённые овощи, протёртые томаты и лавровый лист и готовьте на слабом огне, часто помешивая, чтобы не пригорело, около 40 минут, пока масса не потемнеет, не загустеет и масло не выступит сверху. Посолите по вкусу и удалите лавровый лист. Подавайте холодной, намазав толстым слоем на хлеб — хранится несколько дней в холодильнике.',
      ar:'اشوِ الباذنجان والفلفل كاملاً حتى تتفحّم القشرة ويلين اللبّ، نحو 30 دقيقة، ثم قشّرهما وافرمهما ناعماً. شوّح البصل المفروم في الزيت على نار هادئة حتى يلين ويذهبّ، نحو 10 دقائق. أضف الخضار المشوية والطماطم المهروسة وورقة الغار واطهها بهدوء مع التحريك المتكرر كي لا تلتصق، نحو 40 دقيقة حتى تغمق وتثخن ويطفو الزيت. تبّل بالملح وأخرج ورقة الغار. قدّمها باردة مدهونة بسمك على الخبز — تبقى أياماً في الثلاجة.',
      zh:'把茄子和甜椒整只烤到表皮焦黑、内里软烂，约30分钟，去皮切碎。洋葱末用油小火炒至变软金黄，约10分钟。加入烤好的蔬菜、番茄泥和香叶，小火慢煮并常搅动以免粘底，约40分钟，至颜色变深、变稠、油浮到表面。加盐调味，取出香叶。冷食，厚厚地抹在面包上——冷藏可放数日。',
      ja:'なすとパプリカを丸ごと、皮が真っ黒に焦げて中が柔らかくなるまで約30分焼き、皮をむいて細かく刻む。みじん切りの玉ねぎを油で弱火で柔らかく色づくまで約10分炒める。焼いた野菜、トマトピューレ、ローリエを加え、焦げ付かないようによく混ぜながら約40分、色が濃くなり、とろみがつき、油が上に浮くまで静かに煮る。塩で味を調え、ローリエを取り除く。冷やして、パンに厚く塗って供する——冷蔵庫で数日もつ。',
      hi:'बैंगन और शिमला मिर्च को साबुत तब तक भूनें जब तक छिलका जल जाए और गूदा नरम हो, लगभग 30 मिनट, फिर छीलकर बारीक काटें। कटा प्याज़ तेल में धीमी आँच पर नरम-सुनहरा होने तक लगभग 10 मिनट भूनें। भुनी सब्ज़ियाँ, टमाटर प्यूरी और तेज पत्ता डालें और बार-बार चलाते हुए लगभग 40 मिनट धीमी आँच पर पकाएँ जब तक रंग गहरा हो, गाढ़ा हो और तेल ऊपर आ जाए। नमक डालें और तेज पत्ता निकाल दें। ठंडा, ब्रेड पर मोटा लगाकर परोसें — फ्रिज में कई दिन चलता है।',
      tr:'Patlıcan ve biberleri bütün halde kabuğu kömürleşip içi yumuşayana dek yaklaşık 30 dakika közleyin, sonra soyup ince doğrayın. Doğranmış soğanı yağda kısık ateşte yumuşayıp kızarana dek yaklaşık 10 dakika kavurun. Közlenmiş sebzeleri, domates püresini ve defne yaprağını ekleyip dibe tutmasın diye sık karıştırarak yaklaşık 40 dakika, koyulaşıp rengi kararana ve yağ üste çıkana dek pişirin. Tuzla tatlandırın ve defne yaprağını çıkarın. Soğuk, ekmeğe kalınca sürerek servis edin — buzdolabında günlerce durur.',
      it:'Arrostisci melanzane e peperoni interi finché la buccia si brucia e la polpa si ammorbidisce, circa 30 minuti, poi sbuccia e trita fine. Rosola la cipolla tritata nell’olio a fuoco basso finché è morbida e dorata, circa 10 minuti. Unisci le verdure arrostite, la passata e l’alloro e cuoci piano, mescolando spesso perché non attacchi, circa 40 minuti finché scurisce, si addensa e l’olio affiora. Regola di sale e togli l’alloro. Servi fredda, spalmata spessa sul pane — si conserva giorni in frigo.',
      ko:'가지와 파프리카를 통째로 껍질이 새까맣게 타고 속이 물러질 때까지 약 30분 구운 뒤 껍질을 벗겨 곱게 다진다. 다진 양파를 기름에 약불로 부드럽고 노릇해질 때까지 약 10분 볶는다. 구운 채소, 토마토 퓌레, 월계수 잎을 넣고 눌어붙지 않게 자주 저으며 약 40분, 색이 진해지고 걸쭉해지며 기름이 위로 뜰 때까지 은근히 끓인다. 소금으로 간하고 월계수 잎을 건진다. 차갑게, 빵에 두껍게 발라 낸다 — 냉장고에서 며칠 간다.' } },

  { id:'budget_010', name:NAMES.sarmale, servings:2, prep:25, cook:60, costRon:4, nut:{cal:320,prot:7,carb:52,fat:9,fib:8}, tags:['budget','vegan','family'],
    ing:[ {q:500,u:'g',n:I.cabbage}, {q:120,u:'g',n:I.rice}, {q:1,n:I.onion}, {q:1,n:I.carrot}, {q:150,u:'g',n:I.passata}, {q:3,u:'tbsp',n:I.oil}, {n:I.salt} ],
    steps:{
      ro:'Desprinde foile de varză și opărește-le scurt, ca să se înmoaie și să se ruleze fără să crape. Călește ceapa tocată și morcovul ras în ulei 5 minute, adaugă orezul clătit și jumătate din roșiile pasate și mai gătește 2 minute; potrivește de sare. Pune câte o lingură de umplutură pe fiecare foaie și rulează strâns, îndoind marginile. Așază sarmalele lipite într-o oală, toarnă peste ele restul de roșii pasate și apă cât să le acopere și fierbe blând, acoperit, circa o oră, până varza e fragedă și orezul fiert. Servește cald, tradițional cu mămăligă.',
      en:'Separate the cabbage leaves and blanch them briefly so they soften and roll without cracking. Soften the chopped onion and grated carrot in the oil for 5 minutes, stir in the rinsed rice and half the tomato passata, and cook 2 minutes; season with salt. Put a spoonful of filling on each leaf and roll into a snug parcel, tucking in the sides. Pack the rolls tightly in a pot, pour over the rest of the passata and enough water to cover, and simmer gently, covered, for about an hour until the cabbage is tender and the rice is cooked. Serve warm, traditionally with polenta.',
      es:'Separa las hojas de repollo y escáldalas brevemente para que se ablanden y se enrollen sin romperse. Sofríe la cebolla picada y la zanahoria rallada en el aceite 5 minutos, añade el arroz enjuagado y la mitad del tomate y cocina 2 minutos; sazona con sal. Pon una cucharada de relleno en cada hoja y enrolla apretado, metiendo los lados. Coloca los rollos bien juntos en una olla, cúbrelos con el resto del tomate y agua y cuece tapado a fuego suave una hora, hasta que el repollo esté tierno y el arroz cocido. Sirve caliente, tradicionalmente con polenta.',
      fr:'Détachez les feuilles de chou et blanchissez-les brièvement pour qu’elles s’assouplissent et s’enroulent sans se déchirer. Faites revenir l’oignon haché et la carotte râpée dans l’huile 5 minutes, ajoutez le riz rincé et la moitié des tomates passées et faites cuire 2 minutes ; salez. Déposez une cuillerée de farce sur chaque feuille et roulez serré en rentrant les côtés. Rangez les rouleaux bien serrés dans une casserole, couvrez du reste de tomates et d’eau, et laissez mijoter à couvert environ une heure jusqu’à ce que le chou soit tendre et le riz cuit. Servez chaud, traditionnellement avec de la polenta.',
      de:'Die Kohlblätter ablösen und kurz blanchieren, damit sie weich werden und sich ohne Reißen rollen lassen. Zwiebel gehackt und Karotte gerieben im Öl 5 Minuten anschwitzen, den abgespülten Reis und die Hälfte der passierten Tomaten zugeben und 2 Minuten mitkochen; salzen. Auf jedes Blatt einen Löffel Füllung geben und fest einrollen, die Seiten einschlagen. Die Rouladen dicht in einen Topf schichten, mit den restlichen Tomaten und Wasser bedecken und zugedeckt etwa eine Stunde sanft köcheln, bis der Kohl weich und der Reis gar ist. Warm servieren, traditionell mit Polenta.',
      pt:'Separe as folhas de couve e escalde-as rapidamente para amolecerem e enrolarem sem rachar. Refogue a cebola picada e a cenoura ralada no óleo 5 minutos, junte o arroz lavado e metade do tomate e cozinhe 2 minutos; tempere com sal. Ponha uma colher de recheio em cada folha e enrole bem apertado, dobrando os lados. Disponha os rolinhos bem juntos numa panela, cubra com o resto do tomate e água e cozinhe tapado em lume brando cerca de uma hora, até a couve ficar macia e o arroz cozido. Sirva quente, tradicionalmente com polenta.',
      ru:'Отделите капустные листья и бланшируйте их недолго, чтобы они размякли и сворачивались, не ломаясь. Обжарьте нарезанный лук и тёртую морковь в масле 5 минут, добавьте промытый рис и половину протёртых томатов и готовьте 2 минуты; посолите. На каждый лист положите ложку начинки и сверните плотно, подгибая края. Уложите голубцы плотно в кастрюлю, залейте оставшимися томатами и водой до покрытия и тушите под крышкой около часа, пока капуста не станет мягкой, а рис готовым. Подавайте тёплыми, традиционно с полентой.',
      ar:'افصل أوراق الملفوف واسلقها قليلاً كي تلين وتُلف دون أن تتشقق. شوّح البصل المفروم والجزر المبشور في الزيت 5 دقائق، أضف الأرز المغسول ونصف الطماطم المهروسة واطهه دقيقتين؛ ملّح. ضع ملعقة حشوة على كل ورقة ولفّها بإحكام مع طيّ الجوانب. ارصّ اللفائف متلاصقة في قدر، اسكب فوقها باقي الطماطم وماء يغمرها واطهها مغطاة على نار هادئة نحو ساعة حتى يلين الملفوف وينضج الأرز. قدّمها دافئة، وتقليدياً مع عصيدة الذرة.',
      zh:'把卷心菜叶剥下，稍微焯一下使其变软、卷时不裂。用油炒切碎的洋葱和擦丝的胡萝卜5分钟，加入洗好的米和一半番茄泥再炒2分钟，加盐调味。每片叶子上放一勺馅，收边卷紧。把菜卷紧密码进锅里，倒入剩余番茄泥并加水没过，加盖小火炖约一小时，至卷心菜软、米熟。趁热食用，传统上配玉米粥。',
      ja:'キャベツの葉をはがし、さっと湯通しして、割れずに巻けるよう柔らかくする。みじん切りの玉ねぎとすりおろしにんじんを油で5分炒め、洗った米とトマトピューレの半量を加えて2分炒める；塩で味付けする。各葉に大さじ1杯の詰め物をのせ、両端を折り込んできつく巻く。ロールを鍋に隙間なく詰め、残りのトマトピューレとかぶるくらいの水を注ぎ、ふたをして弱火で約1時間、キャベツが柔らかく米が炊けるまで煮る。温かいうちに、伝統的にはポレンタを添えて供する。',
      hi:'पत्ता गोभी की पत्तियाँ अलग करें और थोड़ा उबालें ताकि नरम हों और बिना फटे लिपट जाएँ। कटा प्याज़ और कद्दूकस गाजर तेल में 5 मिनट भूनें, धुला चावल और आधी टमाटर प्यूरी डालकर 2 मिनट पकाएँ; नमक डालें। हर पत्ती पर एक चम्मच भरावन रखें और किनारे मोड़ते हुए कसकर रोल करें। रोल को बर्तन में सटाकर रखें, ऊपर बची टमाटर प्यूरी और ढकने तक पानी डालें, ढककर धीमी आँच पर लगभग एक घंटा पकाएँ जब तक गोभी नरम और चावल पक जाए। गरम, परंपरागत रूप से पोलेंटा/मामालीगा के साथ परोसें।',
      tr:'Lahana yapraklarını ayırın ve kısa süre haşlayarak yumuşayıp çatlamadan sarılacak hale getirin. Doğranmış soğan ve rendelenmiş havucu yağda 5 dakika kavurun, yıkanmış pirinci ve domates püresinin yarısını ekleyip 2 dakika pişirin; tuzlayın. Her yaprağa bir kaşık iç koyup kenarları katlayarak sıkıca sarın. Sarmaları tencereye sıkışık dizin, üzerine kalan domatesi ve örtecek kadar su ekleyin ve kapağı kapalı kısık ateşte yaklaşık bir saat, lahana yumuşayıp pirinç pişene dek pişirin. Sıcak, geleneksel olarak mısır lapasıyla servis edin.',
      it:'Stacca le foglie di cavolo e sbollentale brevemente perché si ammorbidiscano e si arrotolino senza rompersi. Fai appassire cipolla tritata e carota grattugiata nell’olio per 5 minuti, unisci il riso sciacquato e metà della passata e cuoci 2 minuti; sala. Metti un cucchiaio di ripieno su ogni foglia e arrotola stretto, ripiegando i lati. Disponi gli involtini fitti in una pentola, coprili con il resto della passata e acqua e fai sobbollire coperto circa un’ora, finché il cavolo è tenero e il riso cotto. Servi caldo, tradizionalmente con la polenta.',
      ko:'양배추 잎을 떼어 살짝 데쳐 부드럽게 하여 찢어지지 않게 말 수 있도록 한다. 다진 양파와 채 썬 당근을 기름에 5분 볶고 헹군 쌀과 토마토 퓌레 절반을 넣어 2분 볶은 뒤 소금으로 간한다. 각 잎에 소를 한 숟갈 올리고 양옆을 접어 단단히 만다. 롤을 냄비에 촘촘히 담고 남은 토마토 퓌레와 잠길 만큼의 물을 부어 뚜껑을 덮고 약불에서 약 1시간, 양배추가 부드럽고 쌀이 익을 때까지 끓인다. 따뜻하게, 전통적으로 폴렌타와 함께 낸다.' } },
  { id:'budget_011', name:NAMES.linte, servings:2, prep:10, cook:35, costRon:4, nut:{cal:340,prot:18,carb:50,fat:8,fib:16}, tags:['budget','vegan','high-protein'],
    ing:[ {q:250,u:'g',n:I.lentils}, {q:1,n:I.onion}, {q:2,u:'clove',n:I.garlic}, {q:1,n:I.carrot}, {q:3,u:'tbsp',n:I.oil}, {q:150,u:'g',n:I.passata}, {q:1,n:I.bayLeaf}, {n:I.salt} ],
    steps:{
      ro:'Clătește lintea și alege eventualele impurități. Călește ceapa tocată, usturoiul și morcovul ras în ulei la foc mediu 5 minute. Adaugă lintea, roșiile pasate și foaia de dafin, apoi toarnă apă cât să acopere cu două degete. Fierbe blând, parțial acoperit, circa 30 de minute, până lintea e moale și sosul s-a îngroșat, adăugând un strop de apă dacă scade prea mult. Scoate foaia de dafin, potrivește de sare și servește cald, cu pâine.',
      en:'Rinse the lentils and pick out any grit. Soften the chopped onion, garlic and grated carrot in the oil over medium heat for 5 minutes. Stir in the lentils, the tomato passata and the bay leaf, then pour in enough water to cover by two fingers. Simmer gently, partly covered, for about 30 minutes until the lentils are soft and the sauce has thickened, adding a splash of water if it dries out. Discard the bay leaf, season with salt, and serve warm with bread.',
      es:'Enjuaga las lentejas y retira cualquier impureza. Sofríe la cebolla picada, el ajo y la zanahoria rallada en el aceite a fuego medio 5 minutos. Añade las lentejas, el tomate triturado y la hoja de laurel, y cubre con agua dos dedos por encima. Cuece a fuego suave, parcialmente tapado, unos 30 minutos hasta que las lentejas estén blandas y la salsa espese, añadiendo un poco de agua si se seca. Retira el laurel, sala y sirve caliente con pan.',
      fr:'Rincez les lentilles et retirez les impuretés. Faites revenir l’oignon haché, l’ail et la carotte râpée dans l’huile à feu moyen 5 minutes. Ajoutez les lentilles, les tomates passées et la feuille de laurier, puis couvrez d’eau à deux doigts au-dessus. Laissez mijoter à couvert partiel environ 30 minutes jusqu’à ce que les lentilles soient tendres et la sauce épaisse, en ajoutant un peu d’eau si ça sèche. Retirez le laurier, salez et servez chaud avec du pain.',
      de:'Die Linsen abspülen und verlesen. Zwiebel gehackt, Knoblauch und geriebene Karotte im Öl bei mittlerer Hitze 5 Minuten anschwitzen. Die Linsen, die passierten Tomaten und das Lorbeerblatt zugeben, dann mit Wasser bedecken, zwei Finger breit darüber. Zugedeckt bei schwacher Hitze etwa 30 Minuten köcheln, bis die Linsen weich sind und die Soße eindickt; bei Bedarf etwas Wasser zugeben. Das Lorbeerblatt entfernen, salzen und warm mit Brot servieren.',
      pt:'Enxágue as lentilhas e retire eventuais impurezas. Refogue a cebola picada, o alho e a cenoura ralada no óleo em lume médio 5 minutos. Junte as lentilhas, o tomate passata e a folha de louro, e cubra com água dois dedos acima. Cozinhe em lume brando, parcialmente tapado, cerca de 30 minutos até as lentilhas ficarem macias e o molho engrossar, juntando um pouco de água se secar. Retire o louro, tempere com sal e sirva quente com pão.',
      ru:'Промойте чечевицу и переберите. Обжарьте нарезанный лук, чеснок и тёртую морковь в масле на среднем огне 5 минут. Добавьте чечевицу, протёртые томаты и лавровый лист, затем залейте водой на два пальца выше. Тушите под неполной крышкой около 30 минут, пока чечевица не станет мягкой, а соус не загустеет, подливая воду при необходимости. Удалите лавровый лист, посолите и подавайте тёплым с хлебом.',
      ar:'اغسل العدس وأزل الشوائب. شوّح البصل المفروم والثوم والجزر المبشور في الزيت على نار متوسطة 5 دقائق. أضف العدس والطماطم المهروسة وورقة الغار، ثم غطِّ بالماء بمقدار إصبعين فوقه. اطهه على نار هادئة مع تغطية جزئية نحو 30 دقيقة حتى يلين العدس وتثخن الصلصة، مع إضافة قليل من الماء إذا جفّ. أخرج ورقة الغار وملّح وقدّمه دافئاً مع الخبز.',
      zh:'把扁豆冲洗干净，挑去杂质。中火用油把切碎的洋葱、蒜和擦丝的胡萝卜炒5分钟。加入扁豆、番茄泥和香叶，再加水没过约两指高。半盖小火炖约30分钟，至扁豆软烂、汤汁变稠，太干就加点水。取出香叶，加盐调味，配面包趁热食用。',
      ja:'レンズ豆を洗い、混じり物を取り除く。みじん切りの玉ねぎ、にんにく、すりおろしにんじんを油で中火で5分炒める。レンズ豆、トマトピューレ、ローリエを加え、指二本分かぶるくらいの水を注ぐ。半分ふたをして弱火で約30分、レンズ豆が柔らかくソースがとろりとするまで煮る（乾いたら水を足す）。ローリエを取り除き、塩で味を調え、パンを添えて温かいうちに供する。',
      hi:'मसूर दाल धोकर कंकड़ निकाल लें। कटा प्याज़, लहसुन और कद्दूकस गाजर तेल में मध्यम आँच पर 5 मिनट भूनें। दाल, टमाटर प्यूरी और तेज पत्ता डालें, फिर दो उँगली ऊपर तक पानी डालें। आंशिक ढककर धीमी आँच पर लगभग 30 मिनट पकाएँ जब तक दाल नरम और ग्रेवी गाढ़ी हो जाए, सूखने पर थोड़ा पानी डालें। तेज पत्ता निकालें, नमक डालें और गरम, ब्रेड के साथ परोसें।',
      tr:'Mercimeği yıkayıp ayıklayın. Doğranmış soğan, sarımsak ve rendelenmiş havucu yağda orta ateşte 5 dakika kavurun. Mercimek, domates püresi ve defne yaprağını ekleyin, üzerini iki parmak geçecek kadar suyla örtün. Yarı kapalı, kısık ateşte yaklaşık 30 dakika, mercimek yumuşayıp sos koyulaşana dek pişirin; kuruyunca biraz su ekleyin. Defne yaprağını çıkarın, tuzlayın ve ekmekle sıcak servis edin.',
      it:'Sciacqua le lenticchie e togli eventuali impurità. Fai appassire la cipolla tritata, l’aglio e la carota grattugiata nell’olio a fuoco medio per 5 minuti. Unisci le lenticchie, la passata e l’alloro, poi copri con acqua due dita sopra. Cuoci a fuoco basso, semicoperto, circa 30 minuti finché le lenticchie sono morbide e il sugo si addensa, aggiungendo un po’ d’acqua se asciuga. Togli l’alloro, sala e servi caldo con il pane.',
      ko:'렌틸콩을 헹구고 이물질을 골라낸다. 다진 양파, 마늘, 채 썬 당근을 기름에 중불로 5분 볶는다. 렌틸콩, 토마토 퓌레, 월계수 잎을 넣고 두 손가락 높이만큼 물을 붓는다. 뚜껑을 반쯤 덮고 약불에서 약 30분, 렌틸콩이 부드러워지고 소스가 걸쭉해질 때까지 끓인다(마르면 물을 조금 추가). 월계수 잎을 건지고 소금으로 간해 빵과 함께 따뜻하게 낸다.' } },

  { id:'budget_012', name:NAMES.pilaf, servings:2, prep:10, cook:25, costRon:4, nut:{cal:380,prot:7,carb:68,fat:9,fib:4}, tags:['budget','vegan','family'],
    ing:[ {q:200,u:'g',n:I.rice}, {q:1,n:I.onion}, {q:1,n:I.carrot}, {q:1,n:I.bellPepper}, {q:3,u:'tbsp',n:I.oil}, {q:400,u:'ml',n:I.water}, {n:I.salt} ],
    steps:{
      ro:'Clătește orezul până apa e limpede, apoi scurge-l. Călește ceapa tocată, morcovul ras și ardeiul tăiat cubulețe în ulei 5 minute, apoi adaugă orezul și prăjește-l 2 minute, cât să lucească boabele. Toarnă apa, pune un praf bun de sare și adu la fiert. Acoperă, dă focul la minim și fierbe neatins circa 18 minute, până apa e absorbită. Ia de pe foc și lasă acoperit 10 minute, apoi afânează cu furculița și servește.',
      en:'Rinse the rice until the water runs clear, then drain. Soften the chopped onion, grated carrot and diced pepper in the oil for 5 minutes, then stir in the rice and toast it for 2 minutes so the grains glisten. Pour in the water, add a good pinch of salt, and bring to a boil. Cover, turn the heat right down, and cook undisturbed for about 18 minutes until the water is absorbed. Take off the heat and let it stand, covered, for 10 minutes, then fluff with a fork and serve.',
      es:'Enjuaga el arroz hasta que el agua salga clara y escúrrelo. Sofríe la cebolla picada, la zanahoria rallada y el pimiento en dados en el aceite 5 minutos, añade el arroz y tuéstalo 2 minutos hasta que brille. Vierte el agua, añade una buena pizca de sal y lleva a ebullición. Tapa, baja el fuego al mínimo y cocina sin remover unos 18 minutos hasta que absorba el agua. Retira del fuego y deja reposar tapado 10 minutos, luego suelta con un tenedor y sirve.',
      fr:'Rincez le riz jusqu’à ce que l’eau soit claire, puis égouttez. Faites revenir l’oignon haché, la carotte râpée et le poivron en dés dans l’huile 5 minutes, ajoutez le riz et faites-le nacrer 2 minutes. Versez l’eau, ajoutez une bonne pincée de sel et portez à ébullition. Couvrez, baissez le feu au minimum et laissez cuire sans remuer environ 18 minutes jusqu’à absorption de l’eau. Retirez du feu, laissez reposer à couvert 10 minutes, puis égrenez à la fourchette et servez.',
      de:'Den Reis waschen, bis das Wasser klar ist, dann abtropfen lassen. Zwiebel gehackt, Karotte gerieben und Paprika gewürfelt im Öl 5 Minuten anschwitzen, den Reis zugeben und 2 Minuten glasig rösten. Das Wasser angießen, kräftig salzen und aufkochen. Zudecken, die Hitze ganz herunterdrehen und etwa 18 Minuten ohne Rühren garen, bis das Wasser aufgesogen ist. Vom Herd nehmen, zugedeckt 10 Minuten ruhen lassen, mit der Gabel auflockern und servieren.',
      pt:'Lave o arroz até a água sair limpa e escorra. Refogue a cebola picada, a cenoura ralada e o pimento aos cubos no óleo 5 minutos, junte o arroz e frite 2 minutos até brilhar. Deite a água, tempere com uma boa pitada de sal e leve a ferver. Tape, reduza o lume ao mínimo e cozinhe sem mexer cerca de 18 minutos até absorver a água. Retire do lume, deixe repousar tapado 10 minutos, solte com um garfo e sirva.',
      ru:'Промойте рис до прозрачной воды и откиньте. Обжарьте нарезанный лук, тёртую морковь и перец кубиками в масле 5 минут, добавьте рис и обжаривайте 2 минуты до блеска зёрен. Влейте воду, посолите щедрой щепоткой и доведите до кипения. Накройте, убавьте огонь до минимума и готовьте не перемешивая около 18 минут, пока вода не впитается. Снимите с огня, дайте постоять под крышкой 10 минут, взрыхлите вилкой и подавайте.',
      ar:'اغسل الأرز حتى يصفو الماء ثم صفّه. شوّح البصل المفروم والجزر المبشور والفلفل المكعّب في الزيت 5 دقائق، أضف الأرز وحمّصه دقيقتين حتى يلمع. اسكب الماء وأضف رشة ملح جيدة وارفعه للغليان. غطّه، اخفض النار لأدنى درجة واطهه دون تحريك نحو 18 دقيقة حتى يتشرّب الماء. ارفعه عن النار واتركه مغطى 10 دقائق، ثم فكّكه بالشوكة وقدّمه.',
      zh:'把米淘洗至水清，沥干。用油炒切碎的洋葱、擦丝的胡萝卜和切丁的甜椒5分钟，加入米再炒2分钟至米粒发亮。倒入水，加一大撮盐，煮开。加盖转最小火，不翻动焖约18分钟，至水分收干。离火加盖静置10分钟，用叉子拨松后上桌。',
      ja:'米を水が澄むまで洗い、水を切る。みじん切りの玉ねぎ、すりおろしにんじん、角切りのパプリカを油で5分炒め、米を加えて2分、粒が艶やかになるまで炒める。水を注ぎ、塩をしっかりひとつまみ加えて沸騰させる。ふたをして火を最弱にし、混ぜずに約18分、水分がなくなるまで炊く。火から下ろし、ふたをして10分蒸らし、フォークでほぐして供する。',
      hi:'चावल को पानी साफ आने तक धोकर छान लें। कटा प्याज़, कद्दूकस गाजर और कटी शिमला मिर्च तेल में 5 मिनट भूनें, चावल डालकर 2 मिनट भूनें जब तक दाने चमकने लगें। पानी डालें, एक अच्छी चुटकी नमक डालें और उबाल लाएँ। ढककर आँच बिलकुल धीमी करें और बिना हिलाए लगभग 18 मिनट पकाएँ जब तक पानी सूख जाए। आँच से उतारकर ढककर 10 मिनट रखें, फिर काँटे से खिलाकर परोसें।',
      tr:'Pirinci suyu berraklaşana dek yıkayıp süzün. Doğranmış soğan, rendelenmiş havuç ve küp biberi yağda 5 dakika kavurun, pirinci ekleyip taneler parlayana dek 2 dakika kavurun. Suyu ekleyin, iyi bir tutam tuz atın ve kaynatın. Kapağı kapatıp ateşi en kısığa alın ve karıştırmadan yaklaşık 18 dakika, su çekilene dek pişirin. Ateşten alıp kapalı 10 dakika dinlendirin, çatalla kabartıp servis edin.',
      it:'Sciacqua il riso finché l’acqua è limpida, poi scola. Fai appassire la cipolla tritata, la carota grattugiata e il peperone a dadini nell’olio per 5 minuti, unisci il riso e tostalo 2 minuti finché i chicchi luccicano. Versa l’acqua, aggiungi una bella presa di sale e porta a bollore. Copri, abbassa al minimo e cuoci senza mescolare circa 18 minuti finché l’acqua è assorbita. Togli dal fuoco, lascia riposare coperto 10 minuti, sgrana con la forchetta e servi.',
      ko:'쌀을 물이 맑아질 때까지 씻어 물기를 뺀다. 다진 양파, 채 썬 당근, 깍둑 썬 파프리카를 기름에 5분 볶고 쌀을 넣어 2분, 쌀알이 반질해질 때까지 볶는다. 물을 붓고 소금을 넉넉히 한 꼬집 넣어 끓인다. 뚜껑을 덮고 불을 최소로 줄여 젓지 않고 약 18분, 물이 흡수될 때까지 익힌다. 불에서 내려 뚜껑을 덮은 채 10분 뜸을 들이고 포크로 살살 풀어 낸다.' } },

  { id:'budget_013', name:NAMES.varza, servings:2, prep:15, cook:45, costRon:3, nut:{cal:160,prot:4,carb:18,fat:9,fib:6}, tags:['budget','vegan','healthy'],
    ing:[ {q:600,u:'g',n:I.cabbage}, {q:1,n:I.onion}, {q:4,u:'tbsp',n:I.oil}, {q:150,u:'g',n:I.passata}, {q:1,n:I.bayLeaf}, {q:1,u:'tsp',n:I.paprika}, {n:I.salt} ],
    steps:{
      ro:'Taie varza fideluță și ceapa solzișori. Călește ceapa în ulei 5 minute, apoi adaugă varza și gătește, amestecând des, până se înmoaie și începe să se rumenească, circa 10 minute. Adaugă roșiile pasate, foaia de dafin, boiaua și un praf bun de sare, pune un strop de apă și acoperă. Înăbușă la foc mic circa 30 de minute, amestecând din când în când, până varza e foarte moale și ușor caramelizată. Descoperă în ultimele minute ca să scadă lichidul și servește cald.',
      en:'Shred the cabbage finely and slice the onion. Soften the onion in the oil for 5 minutes, then add the cabbage and cook, stirring often, until it wilts and begins to colour, about 10 minutes. Stir in the tomato passata, the bay leaf, the paprika and a good pinch of salt, add a splash of water, and cover. Braise gently for about 30 minutes, stirring now and then, until the cabbage is very soft and lightly caramelised. Uncover for the last few minutes to cook off the liquid, and serve warm.',
      es:'Corta el repollo en tiras finas y la cebolla en pluma. Sofríe la cebolla en el aceite 5 minutos, añade el repollo y cocina, removiendo a menudo, hasta que se ablande y empiece a dorarse, unos 10 minutos. Incorpora el tomate triturado, la hoja de laurel, el pimentón y una buena pizca de sal, añade un poco de agua y tapa. Guisa a fuego suave unos 30 minutos, removiendo de vez en cuando, hasta que el repollo esté muy tierno y ligeramente caramelizado. Destapa los últimos minutos para reducir el líquido y sirve caliente.',
      fr:'Émincez finement le chou et l’oignon. Faites revenir l’oignon dans l’huile 5 minutes, ajoutez le chou et faites cuire en remuant souvent jusqu’à ce qu’il tombe et commence à dorer, environ 10 minutes. Incorporez les tomates passées, le laurier, le paprika et une bonne pincée de sel, ajoutez un peu d’eau et couvrez. Laissez braiser à feu doux environ 30 minutes, en remuant de temps en temps, jusqu’à ce que le chou soit très tendre et légèrement caramélisé. Découvrez les dernières minutes pour réduire le liquide et servez chaud.',
      de:'Den Kohl fein hobeln und die Zwiebel in Streifen schneiden. Die Zwiebel im Öl 5 Minuten anschwitzen, den Kohl zugeben und unter häufigem Rühren etwa 10 Minuten garen, bis er zusammenfällt und Farbe annimmt. Passierte Tomaten, Lorbeerblatt, Paprikapulver und eine kräftige Prise Salz einrühren, einen Schuss Wasser zugeben und zudecken. Bei schwacher Hitze etwa 30 Minuten schmoren, gelegentlich umrühren, bis der Kohl sehr weich und leicht karamellisiert ist. Zum Schluss den Deckel abnehmen, damit die Flüssigkeit einkocht, und warm servieren.',
      pt:'Corte a couve em tiras finas e a cebola às meias-luas. Refogue a cebola no óleo 5 minutos, junte a couve e cozinhe, mexendo com frequência, até murchar e começar a dourar, cerca de 10 minutos. Junte o tomate passata, a folha de louro, o colorau e uma boa pitada de sal, adicione um pouco de água e tape. Estufe em lume brando cerca de 30 minutos, mexendo de vez em quando, até a couve ficar muito macia e ligeiramente caramelizada. Destape nos últimos minutos para reduzir o líquido e sirva quente.',
      ru:'Нашинкуйте капусту тонко и нарежьте лук полукольцами. Обжарьте лук в масле 5 минут, добавьте капусту и готовьте, часто помешивая, пока не осядет и не начнёт румяниться, около 10 минут. Вмешайте протёртые томаты, лавровый лист, паприку и щедрую щепотку соли, влейте немного воды и накройте. Тушите на слабом огне около 30 минут, изредка помешивая, пока капуста не станет очень мягкой и слегка карамелизуется. В последние минуты снимите крышку, чтобы выпарить жидкость, и подавайте тёплой.',
      ar:'قطّع الملفوف شرائح رفيعة والبصل شرائح. شوّح البصل في الزيت 5 دقائق، أضف الملفوف واطهه مع التحريك المتكرر حتى يذبل ويبدأ بالتحمّر، نحو 10 دقائق. أضف الطماطم المهروسة وورقة الغار والبابريكا ورشة ملح جيدة، أضف قليلاً من الماء وغطِّ. اطهه على نار هادئة نحو 30 دقيقة مع التحريك أحياناً حتى يلين الملفوف جداً ويتكرمل قليلاً. اكشف الغطاء في الدقائق الأخيرة لتبخير السائل وقدّمه دافئاً.',
      zh:'把卷心菜切细丝，洋葱切丝。用油炒洋葱5分钟，加入卷心菜，常翻炒约10分钟，至变软并开始上色。拌入番茄泥、香叶、红椒粉和一大撮盐，加一点水后加盖。小火焖约30分钟，偶尔翻动，至卷心菜非常软烂、微微焦糖化。最后几分钟开盖收汁，趁热食用。',
      ja:'キャベツを細切りにし、玉ねぎを薄切りにする。玉ねぎを油で5分炒め、キャベツを加えてよく混ぜながら約10分、しんなりして色づき始めるまで炒める。トマトピューレ、ローリエ、パプリカ、塩ひとつまみをしっかり混ぜ、水を少し加えてふたをする。弱火で約30分、時々混ぜながら、キャベツがとても柔らかく軽く色づくまで蒸し煮にする。最後の数分はふたを取って水分を飛ばし、温かいうちに供する。',
      hi:'पत्तागोभी को बारीक काटें और प्याज़ को पतला काटें। प्याज़ को तेल में 5 मिनट भूनें, पत्तागोभी डालें और बार-बार चलाते हुए लगभग 10 मिनट भूनें जब तक नरम होकर हल्की सुनहरी होने लगे। टमाटर प्यूरी, तेज पत्ता, पेपरिका और एक अच्छी चुटकी नमक मिलाएँ, थोड़ा पानी डालकर ढक दें। धीमी आँच पर लगभग 30 मिनट पकाएँ, बीच-बीच में चलाते हुए, जब तक पत्तागोभी बहुत नरम और हल्की कैरामेलाइज़ हो जाए। आखिरी कुछ मिनट ढक्कन हटाकर तरल सुखाएँ और गरम परोसें।',
      tr:'Lahanayı ince kıyın, soğanı dilimleyin. Soğanı yağda 5 dakika kavurun, lahanayı ekleyip sık karıştırarak yaklaşık 10 dakika, suyunu salıp renk almaya başlayana dek pişirin. Domates püresi, defne yaprağı, toz biber ve iyi bir tutam tuz ekleyin, biraz su katıp kapağını kapatın. Kısık ateşte yaklaşık 30 dakika, arada karıştırarak, lahana iyice yumuşayıp hafif karamelize olana dek pişirin. Son dakikalarda kapağı açıp suyunu çekin ve sıcak servis edin.',
      it:'Taglia il cavolo a striscioline sottili e la cipolla a fette. Fai appassire la cipolla nell’olio 5 minuti, unisci il cavolo e cuoci, mescolando spesso, finché appassisce e inizia a colorire, circa 10 minuti. Unisci la passata, l’alloro, la paprica e una bella presa di sale, aggiungi un po’ d’acqua e copri. Brasa a fuoco basso circa 30 minuti, mescolando ogni tanto, finché il cavolo è molto morbido e leggermente caramellato. Scopri negli ultimi minuti per far ritirare il liquido e servi caldo.',
      ko:'양배추를 곱게 채 썰고 양파를 얇게 썬다. 양파를 기름에 5분 볶고 양배추를 넣어 자주 저으며 약 10분, 숨이 죽고 색이 나기 시작할 때까지 볶는다. 토마토 퓌레, 월계수 잎, 파프리카 가루, 소금 넉넉히 한 꼬집을 섞고 물을 조금 넣어 뚜껑을 덮는다. 약불에서 약 30분, 가끔 저으며 양배추가 아주 부드럽고 살짝 캐러멜화될 때까지 조린다. 마지막 몇 분은 뚜껑을 열어 수분을 날리고 따뜻하게 낸다.' } },

  { id:'budget_014', name:NAMES.oua, servings:2, prep:5, cook:15, costRon:4, nut:{cal:240,prot:14,carb:9,fat:16,fib:3}, tags:['budget','vegetarian','quick'],
    ing:[ {q:4,n:I.eggs}, {q:400,u:'g',n:I.tomatoes}, {q:1,n:I.onion}, {q:2,u:'tbsp',n:I.oil}, {n:I.salt} ],
    steps:{
      ro:'Toacă ceapa și taie roșiile bucățele. Călește ceapa în ulei la foc mediu 4 minute, apoi adaugă roșiile și un praf de sare și gătește până se transformă într-un sos gros, circa 8 minute. Bate ușor ouăle, toarnă-le peste roșii și amestecă blând cu o lingură de lemn până se leagă, dar rămân cremoase, circa 2 minute. Ia de pe foc cât încă sunt moi — se gătesc mai departe în tigaia fierbinte. Servește imediat, cu pâine.',
      en:'Chop the onion and cut the tomatoes into small pieces. Soften the onion in the oil over medium heat for 4 minutes, then add the tomatoes and a pinch of salt and cook until they collapse into a thick sauce, about 8 minutes. Beat the eggs lightly, pour them over the tomatoes, and stir gently with a wooden spoon until just set but still creamy, about 2 minutes. Take off the heat while soft — they keep cooking in the hot pan. Serve straight away with bread.',
      es:'Pica la cebolla y corta los tomates en trozos pequeños. Sofríe la cebolla en el aceite a fuego medio 4 minutos, añade los tomates y una pizca de sal y cocina hasta que se deshagan en una salsa espesa, unos 8 minutos. Bate ligeramente los huevos, viértelos sobre el tomate y remueve con suavidad con una cuchara de madera hasta que cuajen pero sigan cremosos, unos 2 minutos. Retira del fuego cuando aún estén jugosos — siguen cocinándose en la sartén caliente. Sirve enseguida con pan.',
      fr:'Hachez l’oignon et coupez les tomates en petits morceaux. Faites revenir l’oignon dans l’huile à feu moyen 4 minutes, ajoutez les tomates et une pincée de sel et faites cuire jusqu’à obtenir une sauce épaisse, environ 8 minutes. Battez légèrement les œufs, versez-les sur les tomates et remuez doucement à la cuillère en bois jusqu’à ce qu’ils prennent tout en restant crémeux, environ 2 minutes. Retirez du feu tant qu’ils sont moelleux — ils continuent de cuire dans la poêle chaude. Servez aussitôt avec du pain.',
      de:'Die Zwiebel hacken und die Tomaten klein schneiden. Die Zwiebel im Öl bei mittlerer Hitze 4 Minuten anschwitzen, die Tomaten und eine Prise Salz zugeben und kochen, bis sie zu einer dicken Soße zerfallen, etwa 8 Minuten. Die Eier leicht verquirlen, über die Tomaten gießen und mit einem Holzlöffel sanft rühren, bis sie gerade stocken, aber cremig bleiben, etwa 2 Minuten. Vom Herd nehmen, solange sie weich sind — sie garen in der heißen Pfanne nach. Sofort mit Brot servieren.',
      pt:'Pique a cebola e corte os tomates em pedaços pequenos. Refogue a cebola no óleo em lume médio 4 minutos, junte os tomates e uma pitada de sal e cozinhe até desfazerem num molho espesso, cerca de 8 minutos. Bata ligeiramente os ovos, deite-os sobre o tomate e mexa com suavidade com uma colher de pau até ganharem consistência mas ficarem cremosos, cerca de 2 minutos. Retire do lume enquanto ainda macios — continuam a cozer na frigideira quente. Sirva de imediato com pão.',
      ru:'Нарежьте лук и порежьте помидоры небольшими кусочками. Обжарьте лук в масле на среднем огне 4 минуты, добавьте помидоры и щепотку соли и готовьте, пока они не разварятся в густой соус, около 8 минут. Слегка взбейте яйца, вылейте их на помидоры и осторожно помешивайте деревянной ложкой, пока не схватятся, но останутся нежными, около 2 минут. Снимите с огня, пока мягкие — они дойдут на горячей сковороде. Подавайте сразу с хлебом.',
      ar:'افرم البصل وقطّع الطماطم قطعاً صغيرة. شوّح البصل في الزيت على نار متوسطة 4 دقائق، أضف الطماطم ورشة ملح واطهها حتى تتحوّل إلى صلصة كثيفة، نحو 8 دقائق. اخفق البيض قليلاً، اسكبه فوق الطماطم وحرّكه برفق بملعقة خشب حتى يتماسك مع بقائه طرياً، نحو دقيقتين. ارفعه عن النار وهو طري — يستمر في النضج في المقلاة الساخنة. قدّمه فوراً مع الخبز.',
      zh:'洋葱切碎，番茄切小块。中火用油炒洋葱4分钟，加入番茄和一撮盐，煮约8分钟至化成浓稠的酱。把鸡蛋略微打散，倒在番茄上，用木勺轻轻搅动约2分钟，至刚凝固但仍嫩滑。趁蛋还软时离火——在热锅里会继续熟。配面包立即上桌。',
      ja:'玉ねぎをみじん切りにし、トマトを小さく切る。玉ねぎを油で中火で4分炒め、トマトと塩ひとつまみを加えて約8分、とろりとしたソースになるまで煮る。卵を軽く溶き、トマトに流し入れ、木べらでやさしく混ぜて、固まりつつもとろりとするまで約2分火を通す。柔らかいうちに火から下ろす——熱いフライパンで火が入り続ける。すぐにパンを添えて供する。',
      hi:'प्याज़ काटें और टमाटर छोटे टुकड़ों में काटें। प्याज़ को तेल में मध्यम आँच पर 4 मिनट भूनें, टमाटर और एक चुटकी नमक डालें और लगभग 8 मिनट पकाएँ जब तक गाढ़ी चटनी बन जाए। अंडों को हल्का फेंटें, टमाटर के ऊपर डालें और लकड़ी के चम्मच से हल्के हाथ से लगभग 2 मिनट चलाएँ जब तक जम जाएँ पर मलाईदार रहें। नरम रहते ही आँच से उतारें — गरम पैन में पकते रहते हैं। तुरंत ब्रेड के साथ परोसें।',
      tr:'Soğanı doğrayın, domatesleri küçük parçalara kesin. Soğanı yağda orta ateşte 4 dakika kavurun, domatesleri ve bir tutam tuzu ekleyip koyu bir sos olana dek yaklaşık 8 dakika pişirin. Yumurtaları hafifçe çırpın, domateslerin üzerine dökün ve tahta kaşıkla nazikçe, tutana ama kremamsı kalana dek yaklaşık 2 dakika karıştırın. Yumuşakken ateşten alın — sıcak tavada pişmeye devam eder. Hemen ekmekle servis edin.',
      it:'Trita la cipolla e taglia i pomodori a pezzetti. Fai appassire la cipolla nell’olio a fuoco medio 4 minuti, unisci i pomodori e un pizzico di sale e cuoci finché si disfano in un sugo denso, circa 8 minuti. Sbatti leggermente le uova, versale sui pomodori e mescola delicatamente con un cucchiaio di legno finché rapprendono ma restano cremose, circa 2 minuti. Togli dal fuoco quando sono ancora morbide — continuano a cuocere nella padella calda. Servi subito con il pane.',
      ko:'양파를 다지고 토마토를 작게 썬다. 양파를 기름에 중불로 4분 볶고 토마토와 소금 한 꼬집을 넣어 약 8분, 걸쭉한 소스가 될 때까지 익힌다. 달걀을 가볍게 풀어 토마토 위에 붓고 나무 주걱으로 부드럽게 약 2분, 막 엉기되 크리미함이 남을 때까지 저어준다. 부드러울 때 불에서 내린다 — 뜨거운 팬에서 계속 익는다. 빵을 곁들여 바로 낸다.' } },

  { id:'budget_015', name:NAMES.macaroane, servings:2, prep:10, cook:30, costRon:5, nut:{cal:480,prot:20,carb:58,fat:18,fib:3}, tags:['budget','vegetarian','family'],
    ing:[ {q:250,u:'g',n:I.pasta}, {q:150,u:'g',n:I.cheese}, {q:100,u:'g',n:I.sourCream}, {q:2,n:I.eggs}, {q:30,u:'g',n:I.butter}, {n:I.salt} ],
    steps:{
      ro:'Fierbe macaroanele în apă cu sare până sunt abia moi, apoi scurge-le. Amestecă pastele scurse cu cea mai mare parte din brânza sfărâmată, smântâna și ouăle bătute ușor, și potrivește cu puțină sare. Unge un vas de copt cu puțin unt, răstoarnă pastele și presară deasupra restul de brânză și unt. Coace la 200°C circa 20 de minute, până se leagă și se rumenește deasupra. Lasă să se odihnească 5 minute ca să se închege, apoi taie pătrate și servește cald.',
      en:'Boil the macaroni in salted water until just tender, then drain. Mix the drained pasta with most of the crumbled cheese, the sour cream and the lightly beaten eggs, and season with a little salt. Rub an oven dish with some of the butter, tip in the pasta, and scatter the rest of the cheese and butter on top. Bake at 200°C for about 20 minutes until set and golden. Let it rest for 5 minutes so it firms up, then cut into squares and serve warm.',
      es:'Cuece los macarrones en agua con sal hasta que estén al dente, luego escúrrelos. Mezcla la pasta escurrida con la mayor parte del queso desmenuzado, la crema agria y los huevos ligeramente batidos, y sazona con un poco de sal. Unta una fuente de horno con parte de la mantequilla, vuelca la pasta y reparte por encima el resto del queso y la mantequilla. Hornea a 200°C unos 20 minutos hasta que cuaje y se dore. Deja reposar 5 minutos para que asiente, corta en cuadrados y sirve caliente.',
      fr:'Faites cuire les macaronis dans l’eau salée jusqu’à ce qu’ils soient juste tendres, puis égouttez. Mélangez les pâtes égouttées avec la majeure partie du fromage émietté, la crème aigre et les œufs légèrement battus, et salez un peu. Beurrez un plat à four, versez les pâtes et parsemez du reste de fromage et de beurre. Enfournez à 200°C environ 20 minutes jusqu’à ce que ce soit pris et doré. Laissez reposer 5 minutes pour que ça se raffermisse, coupez en carrés et servez chaud.',
      de:'Die Makkaroni in Salzwasser knapp gar kochen, dann abgießen. Die abgetropften Nudeln mit dem größten Teil des zerbröckelten Käses, dem Schmand und den leicht verquirlten Eiern mischen und mit etwas Salz würzen. Eine Auflaufform mit etwas Butter einfetten, die Nudeln einfüllen und den restlichen Käse und die Butter darüber verteilen. Bei 200 °C etwa 20 Minuten backen, bis alles fest und goldbraun ist. 5 Minuten ruhen lassen, damit es fest wird, in Quadrate schneiden und warm servieren.',
      pt:'Coza o macarrão em água com sal até ficar al dente, depois escorra. Misture a massa escorrida com a maior parte do queijo esfarelado, as natas azedas e os ovos ligeiramente batidos, e tempere com um pouco de sal. Unte um prato de forno com parte da manteiga, deite a massa e espalhe por cima o resto do queijo e da manteiga. Leve ao forno a 200°C cerca de 20 minutos até ganhar consistência e dourar. Deixe repousar 5 minutos para firmar, corte em quadrados e sirva quente.',
      ru:'Отварите макароны в подсолённой воде до состояния аль денте, затем откиньте. Смешайте макароны с большей частью раскрошенной брынзы, сметаной и слегка взбитыми яйцами, немного посолите. Смажьте форму для запекания частью масла, выложите макароны и посыпьте оставшейся брынзой и маслом. Запекайте при 200 °C около 20 минут, пока не схватится и не подрумянится. Дайте постоять 5 минут, чтобы уплотнилось, нарежьте квадратами и подавайте тёплым.',
      ar:'اسلق المعكرونة في ماء مملّح حتى تلين قليلاً ثم صفّها. اخلط المعكرونة المصفّاة مع معظم الجبن المفتّت والقشدة الحامضة والبيض المخفوق قليلاً، وملّحها قليلاً. ادهن طبق فرن بقليل من الزبدة، اسكب المعكرونة ووزّع فوقها باقي الجبن والزبدة. اخبزها على 200 °م نحو 20 دقيقة حتى تتماسك وتذهبّ. اتركها 5 دقائق لتتماسك، ثم قطّعها مربّعات وقدّمها دافئة.',
      zh:'把通心粉在盐水中煮到刚变软，沥干。将沥干的面与大部分掰碎的奶酪、酸奶油和略微打散的鸡蛋拌匀，加少许盐调味。用少许黄油涂抹烤盘，倒入面，把剩下的奶酪和黄油撒在上面。200°C烤约20分钟，至凝固、表面金黄。静置5分钟使其定形，切成方块趁热食用。',
      ja:'マカロニを塩湯でぎりぎり柔らかくなるまで茹で、湯を切る。水気を切ったパスタを、崩したチーズの大部分、サワークリーム、軽く溶いた卵と混ぜ、塩少々で調味する。耐熱皿にバターを薄く塗り、パスタを入れ、残りのチーズとバターを上に散らす。200℃で約20分、固まって焼き色がつくまで焼く。5分ほど休ませて落ち着かせ、四角に切って温かいうちに供する。',
      hi:'मैकरोनी को नमकीन पानी में बस नरम होने तक उबालें, फिर छान लें। छनी पास्ता को अधिकांश चूरा की हुई चीज़, खट्टी क्रीम और हल्के फेंटे अंडों के साथ मिलाएँ, थोड़ा नमक डालें। बेकिंग डिश पर थोड़ा मक्खन लगाएँ, पास्ता डालें और ऊपर बची चीज़ और मक्खन बिखेरें। 200°C पर लगभग 20 मिनट बेक करें जब तक जम जाए और ऊपर से सुनहरा हो जाए। 5 मिनट रखें ताकि सेट हो जाए, फिर चौकोर काटकर गरम परोसें।',
      tr:'Makarnayı tuzlu suda yumuşayana dek haşlayıp süzün. Süzülmüş makarnayı ufalanmış peynirin çoğu, ekşi krema ve hafifçe çırpılmış yumurtalarla karıştırın, biraz tuz ekleyin. Fırın kabını biraz tereyağıyla yağlayın, makarnayı dökün ve kalan peynir ile tereyağını üzerine serpin. 200°C’de yaklaşık 20 dakika, tutup üzeri kızarana dek pişirin. 5 dakika dinlendirip sertleşmesini bekleyin, kare kesip sıcak servis edin.',
      it:'Lessa i maccheroni in acqua salata finché sono appena teneri, poi scola. Mescola la pasta scolata con gran parte del formaggio sbriciolato, la panna acida e le uova leggermente sbattute, e sala leggermente. Ungi una pirofila con un po’ di burro, versa la pasta e distribuisci sopra il formaggio e il burro rimasti. Inforna a 200°C circa 20 minuti finché rapprende e dora. Lascia riposare 5 minuti perché si compatti, taglia a quadrotti e servi caldo.',
      ko:'마카로니를 소금물에 막 부드러워질 때까지 삶아 물기를 뺀다. 물기 뺀 파스타를 부순 치즈 대부분, 사워크림, 가볍게 푼 달걀과 섞고 소금으로 살짝 간한다. 오븐 그릇에 버터를 조금 바르고 파스타를 담은 뒤 남은 치즈와 버터를 위에 뿌린다. 200°C에서 약 20분, 엉기고 윗면이 노릇해질 때까지 굽는다. 5분간 두어 굳힌 뒤 네모나게 잘라 따뜻하게 낸다.' } },
];

const recipes = SPECS.map(mk);

export { recipes };
export default recipes;
export const BUDGET_RECIPES = recipes;

if (typeof window !== 'undefined') {
  window.BUDGET_RECIPES = recipes;
}
